\label{conj-HLC}
	For any integer $k,\, \ell \geqslant 0$, let $h_1, \ldots, h_k, a_1, \ldots, a_{\ell}$ be distinct integers. Then we have 
	\begin{equation}\label{HLC-conj}
		\sum_{n \leqslant x} \mu(n+h_1) \cdots \mu(n+h_k) 
		\Lambda(n+a_1) \cdots \Lambda(n+a_{\ell})
		=\big(\mathfrak{S}_{k,\, \ell}+o(1)\big) x.
	\end{equation}
where $\mathfrak{S}_{k, \ell} = \mathfrak{S}_{\ell}$ as in \eqref{eq:HL-singular-series} if $k=0$ and $\mathfrak{S}_{k, \ell} =0$ if $k>0$. In particular, when $k=\ell=1$ and $a_1=0$, then \eqref{HLC-conj} reduces to the M\"obius function on shifted primes:
	$\sum_{n \leqslant x} \mu\bigl(n+h_1\bigr)  \Lambda(n) =o(x),$
or equivalently
\begin{align}\label{HLC-1-0}
	\sum_{p \leqslant x} \mu\bigl(p+h_1\bigr) =o\big(\pi(x)\big).
\end{align}

\label{thm:main}
	As $x\to\infty$, we have
\begin{equation*}
	\sum_{p\leqslant x}\mu(p+2)=o(\pi(x)).
\end{equation*}

\label{thm2}
	For each $\kappa\in\{-1,1\}$, as $x\to\infty$, one has
	\begin{equation*}
		\#\Big\{p\leqslant x:\ \mu(p+2)=\kappa\Big\}
		=\bigg(\frac{A_2}{2}+o(1)\bigg)\pi(x),
	\end{equation*}
	where $A_2$ is a positive constant defined by
	\begin{align*}
		A_2:=\prod_{p>2}\bigg(1-\frac{1}{p(p-1)}\bigg).
	\end{align*}
	In particular, among the primes $p$ for which $\mu^2(p+2)=1$, each of  the values $1$ and $-1$ occur with asymptotic density $1/2$:
	\begin{equation*}
		\lim_{x\to\infty}
		\frac{\big|\big\{p\leqslant x:\ \mu(p+2)=\kappa\big\}\big|}
		{\big|\big\{p\leqslant x:\ \mu^2(p+2)=1\big\}\big|}
		=\frac12,
		\quad \kappa\in\{-1,\,1\}.
	\end{equation*}

\label{prop:vau}
If $F$ is bounded on $(x,2x]$, then
\begin{equation}\label{eq:vaughan}
\begin{aligned}
\sum_{x<n\leqslant2x}\Lambda(n)F(n)
=T_1(F)-T_2(F)+T_3(F)+O\big(\|F\|_\infty Z\big),
\end{aligned}
\end{equation}
where
\begin{equation*} 
\begin{aligned}
T_1(F)&=\sum_{d\leqslant U}\mu(d)R_Z(d)
 \sum_{x<dk\leqslant2x}R_Z(k)(\log k)F(dk),\\
T_2(F)&=\sum_{\substack{d\leqslant U\\\ell\leqslant V}}
 \mu(d)\Lambda(\ell)R_Z(d\ell)
 \sum_{x<d\ell k\leqslant2x}R_Z(k)F(d\ell k),\\
T_3(F)&=\sum_{\substack{d>U,\, r>V\\x<dr\leqslant2x}}
 \mu(d)R_Z(d)c_V(r)R_Z(r)F(dr).
\end{aligned}
\end{equation*}
We refer to $T_1(F)$ and $T_2(F)$ as the Type I sums, and to $T_3(F)$ as the Type II sum.

For every positive integer $n$, Vaughan's identity gives
	\begin{equation}\label{eq:vauid}
		\begin{aligned}
			\Lambda(n)
			=\Lambda(n)\mathbf{1}_{n\leqslant V}
			+\sum_{\substack{dk=n\\d\leqslant U}}\mu(d)\log k
			-\sum_{\substack{d\ell k=n\\d\leqslant U,\,\ \ell\leqslant V}}
			\mu(d)\Lambda(\ell)
			+\sum_{\substack{d\ell k=n\\d>U,\,\ \ell>V}}
			\mu(d)\Lambda(\ell).
		\end{aligned}
	\end{equation}
For $x<n\leqslant2x$, the first term of \eqref{eq:vauid}
is zero, since $V<x$. By the definition of $c_V(r)$ above, we multiply \eqref{eq:vauid} by $R_Z(n)F(n)$ and sum over $x<n\leqslant2x$, getting
\begin{equation}\label{eq:vaughan-sifted-sum}
	\sum_{x<n\leqslant2x}\Lambda(n)R_Z(n)F(n)
	=T_1(F)-T_2(F)+T_3(F).
\end{equation}
For a prime power $p^j$, we have $R_Z(p^j)=0$
if and only if $p\leqslant Z$. Hence
\begin{align*}
	\bigg|\sum_{x<n\leqslant2x}\Lambda(n)F(n)
	-\sum_{x<n\leqslant2x}\Lambda(n)R_Z(n)F(n)\bigg|
	=\bigg|\sum_{p\leqslant Z}
	\sum_{\substack{j\geqslant1\\x<p^j\leqslant2x}}
	(\log p)F(p^j)\bigg|\ll\|F\|_\infty Z.
\end{align*}
Combining this estimate with \eqref{eq:vaughan-sifted-sum}, we conclude \eqref{eq:vaughan}.

\label{prop:mel}
Let $\delta,\,B,\,C>0$ be fixed. Suppose that
$x^\delta\leqslant D\leqslant2x$ and $I\subseteq[D,2D]$ is an interval.
Let $\chi$ be a Dirichlet character modulo $q$ with $1\leqslant q\leqslant (\log x)^B$. Then for any $A>0$
\begin{equation}\label{eq:mellin}
	\sup_{|t|\leqslant x^C}
	\bigg|\sum_{d\in I}\mu(d)R_Z(d)\chi(d)d^{it}\bigg|
	\ll_{A,\,B,\,C,\,\delta}D L^{-A}.
\end{equation}

Let $\mathcal X\geqslant3$ and $1\leqslant r\leqslant\mathcal X$. Let $\alpha_0\in(0,1]$ be fixed.
Then for any character $\chi$ (mod $q$) with $q\leqslant (\log\mathcal X)^{A_0}$ and any $A_0>0$, one has (see \cite[Lemma 3.9(ii)]{MSTT})
\begin{equation}\label{eq:muinput}
\begin{aligned}
\sup_{|t|\leqslant\mathcal X}
 \sup_{I\subset[\mathcal X^{\alpha_0},\,2\mathcal X^{\alpha_0}]}
 \biggl|\sum_{n\in I}\frac{\mu(rn)\chi(n)}{n^{1/2+it}}\biggr|
 \ll_{\alpha_0,\,A_0}
 \mathcal X^{\alpha_0/2}(\log\mathcal X)^{-A_0}.
\end{aligned}
\end{equation}

Let $H$ satisfy $x^{\delta/2}\leqslant H\leqslant2x$.
We first consider the sum over subintervals of $[H,\,2H]$. 
Choose $R>\max\{1,\,2(C+1)/\delta\}$ depending only on
$\delta$ and $C$, and put
\begin{equation*}
	\mathcal X=H^R,\,\qquad \alpha_0=1/R.
\end{equation*}
Then $H=\mathcal X^{\alpha_0}$ and
$\mathcal X\geqslant x^{R\delta/2}>x^{C+1}$, so the range
$|t|\leqslant x^C$ is covered by that in \eqref{eq:muinput}.

For each fixed $A_0$, the implied constant in
\eqref{eq:muinput} is independent of $H$, because
$\alpha_0=1/R$ is fixed. Also,
$\log\mathcal X\asymp_{\delta,\,C}L$.

Increase $A_0$ to cover the modulus range and the required saving, replace $t$ by $-t$, and apply
partial summation only to the real weight $n^{1/2}$. This gives
\begin{equation}\label{eq:muplain}
\begin{aligned}
\sup_{|t|\leqslant x^C}\sup_{I\subset[H,\,2H]}
 \bigl|\sum_{n\in I}\mu(n)\chi(n)n^{it}\bigr|
 \ll_{A,\,B,\,C,\,\delta}H L^{-A}.
\end{aligned}
\end{equation}
The passage from \eqref{eq:muinput} to \eqref{eq:muplain} does not differentiate $n^{it}$, so it
incurs no loss in $|t|$.

The following identity
\begin{equation*}
\begin{aligned}
\mu(n)R_Z(n)=\sum_{\substack{a\mid n\\P^+(a)\leqslant Z}}\mu(n/a),
\end{aligned}
\end{equation*}
handles the indicator $R_Z(n)$. It can be checked prime by prime:
for $p\leqslant Z$, the right-hand side at $p^j$ is $1-1=0$ for $j\geqslant1$, whereas for $p>Z$ it is
$\mu(p^j)$. The sum on the left of \eqref{eq:mellin} therefore equals
\begin{equation}\label{eq:musum}
\begin{aligned}
\sum_{\substack{a\leqslant2D\\P^+(a)\leqslant Z}}\chi(a)a^{it}
\sum_{k\in I/a}\mu(k)\chi(k)k^{it}.                 
\end{aligned}
\end{equation}
For $a\leqslant D^{1/2}$, put $H=D/a$. Then
$I/a\subseteq[H,\,2H]$ and $x^{\delta/2}\leqslant H\leqslant2x$.
Applying \eqref{eq:muplain} with $A$ replaced by $A+1$,
we obtain
\begin{equation*}
	\sup_{|t|\leqslant x^C}
	\bigg|\sum_{k\in I/a}\mu(k)\chi(k)k^{it}\bigg|
	\ll_{A,\,B,\,C,\,\delta}\frac{D}{a}L^{-A-1}.
\end{equation*}
Moreover, one has
\begin{equation*}
	\sum_{P^+(a)\leqslant Z}\frac1a
	=\prod_{p\leqslant Z}(1-p^{-1})^{-1}
	\ll\log Z,
\end{equation*}
whence, by $\log Z=L^{0.24}$
\begin{align*}
	\sup_{|t|\leqslant x^C}
	\bigg|
	\sum_{\substack{a\leqslant D^{1/2}\\P^+(a)\leqslant Z}}
	\chi(a)a^{it}\sum_{k\in I/a}\mu(k)\chi(k)k^{it}
	\bigg|
	\ll	DL^{-A-1}
	\sum_{\substack{a\leqslant D^{1/2}\\P^+(a)\leqslant Z}}\frac1a
	\ll DL^{-A}.
\end{align*}

For $a>D^{1/2}$, take $\eta=1/\log Z$. Rankin's trick gives
\begin{equation}\label{eq:smtail}
\begin{aligned}
\sum_{\substack{a>D^{1/2}\\P^+(a)\leqslant Z}}\frac1a
\leqslant D^{-\frac{\eta}{2}}\prod_{p\leqslant Z}(1-p^{-1+\eta})^{-1}\ll \exp\biggl(-\frac{\log D}{2\log Z}\biggr)\log Z
\ll L^{0.24}\exp(-c_\delta L^{0.76}).
\end{aligned}
\end{equation}
For the second inequality we used
\begin{equation*}
\begin{aligned}
\log\frac{\prod_{p\leqslant Z}(1-p^{-1+\eta})^{-1}}
              {\prod_{p\leqslant Z}(1-p^{-1})^{-1}}
=\sum_{p\leqslant Z}\sum_{j\geqslant1}
       \frac{p^{-j(1-\eta)}-p^{-j}}j\ll\sum_{p\leqslant Z}\frac{p^\eta-1}p
 \ll\eta\sum_{p\leqslant Z}\frac{\log p}p\ll1,
\end{aligned}
\end{equation*}
since $\eta=1/\log Z$.
The inner sum
in \eqref{eq:musum} has at most $2D/a$ terms, so \eqref{eq:smtail} proves the required saving for
$a>D^{1/2}$.

\label{prop:rem}
	For $1\leqslant j\leqslant b$, let $\mathcal W_j$ be a weight of the form
	\eqref{eq:mark}, constructed from $K$ sets of primes as in
	\eqref{eq:prime-sets}. Define $m_j$ by \eqref{eq:markexp}
	with $\mathcal W$ replaced by $\mathcal W_j$.
	Assume that the prime sets for different weights have no primes in common. Then
	\begin{equation}\label{eq:004}
		\begin{aligned}
			\frac1x\sum_{x<p\leqslant2x}\log p
			\biggl(\frac1b\sum_{j=1}^b
			\frac{\mathcal W_j(p+2)}{m_j}-1\biggr)^2
			\leqslant\frac{C_{K,\,\rho}}b+o(1).
		\end{aligned}
	\end{equation}
	Here $b,K$ and all exponents are fixed before $x\to\infty$.

Let $\mathcal F$ be either $\mathcal W_j$ or $\mathcal W_j\mathcal W_k$ with $j\ne k$. There are $K$ prime sets in the first case and $2K$ in the second. Denote their number by $s$ and write them as $\mathcal P_1,\ldots,\mathcal P_s$. Thus
	\begin{equation*}
		\mathcal F(n)=\prod_{i=1}^{s}\frac{\omega_i(n)\rho^{\omega_i(n)-1}}{V_i}.
	\end{equation*}

	Choosing $\ell$ distinct primes from $\{p\in\mathcal P_i:p\mid n\}$ is equivalent to choosing a squarefree divisor of $n$ with $\ell$ prime factors, all in $\mathcal P_i$. Hence
	\begin{equation*}
		\binom{\omega_i(n)}{\ell}=\sum_{\substack{d\mid n,\,\mu^2(d)=1\\p\mid d\Rightarrow p\in\mathcal P_i,\,\omega(d)=\ell}}1.
	\end{equation*}
	Differentiating $\rho^u=\sum_{\ell=0}^{u}\binom u\ell(\rho-1)^\ell$ gives
	\begin{equation}\label{eq:005}
		u\rho^{u-1}=\sum_{\ell=1}^{u}\ell(\rho-1)^{\ell-1}\binom u\ell\qquad(u\geqslant0),
	\end{equation}
	where $u$ is an integer and the sum is empty when $u=0$.

	For an integer $R\geqslant1$, define
	\begin{equation*}
		\mathcal F_R(n)=\prod_{i=1}^{s}\biggl\{\frac1{V_i}\sum_{\ell=1}^{R}\ell(\rho-1)^{\ell-1}\binom{\omega_i(n)}{\ell}\biggr\},
	\end{equation*}
	with $\binom{\omega_i(n)}{\ell}=0$ for $\ell>\omega_i(n)$. Subtracting this expression from the full expansion gives
	\begin{equation*}
		\mathcal F(n)-\mathcal F_R(n)=\sum_{\substack{\ell_1,\ldots,\ell_s\geqslant1\\\max_{1\leqslant i\leqslant s}\ell_i>R}}\prod_{i=1}^{s}\biggl\{\frac{\ell_i(\rho-1)^{\ell_i-1}}{V_i}\binom{\omega_i(n)}{\ell_i}\biggr\}.
	\end{equation*}

	We first estimate this difference averaged over integers. For each $i$, we have
	\begin{equation*}
		\sum_{\substack{\mu^2(d)=1,\,\omega(d)=\ell\\p\mid d\Rightarrow p\in\mathcal P_i}}\frac1d\leqslant\frac{V_i^\ell}{\ell!}.
	\end{equation*}
	Divisors supported on different $\mathcal P_i$ are coprime. Expanding the binomial coefficients and using $\lfloor3x/(d_1\cdots d_s)\rfloor\leqslant3x/(d_1\cdots d_s)$ therefore gives
	\begin{equation*}
		\sum_{n\leqslant3x}\prod_{i=1}^{s}\binom{\omega_i(n)}{\ell_i}\leqslant3x\prod_{i=1}^{s}\frac{V_i^{\ell_i}}{\ell_i!}.
	\end{equation*}
	Since $V_i=\log2+o(1)<1$ for sufficiently large $x$, we have
	\begin{equation*}
		\sum_{\ell\geqslant1}\frac{((1-\rho)V_i)^{\ell-1}}{(\ell-1)!}\leqslant e,\qquad \sum_{\ell>R}\frac{((1-\rho)V_i)^{\ell-1}}{(\ell-1)!}\leqslant\frac e{R!}.
	\end{equation*}
	In every omitted term, at least one $\ell_i$ exceeds $R$. Summing over the possible choices of this index yields
	\begin{equation}
		\begin{aligned}
			\sum_{n\leqslant3x}|\mathcal F(n)-\mathcal F_R(n)|&\leqslant3x\sum_{\substack{\ell_1,\ldots,\ell_s\geqslant1\\\max_{1\leqslant i\leqslant s}\ell_i>R}}\prod_{i=1}^{s}\frac{((1-\rho)V_i)^{\ell_i-1}}{(\ell_i-1)!}\\
			&\leqslant\frac{3se^s x}{R!}\ll_{K,\,\rho}\frac{x}{R!}.
		\end{aligned}
	\end{equation}

	We next estimate the difference over reduced residue classes. Let $P$ be the product of all primes used to define $\mathcal W_1,\ldots,\mathcal W_b$. Since $P$ is odd, the Chinese remainder theorem gives
	\begin{equation*}
		\frac1{\varphi(P)}\sum_{\substack{a\,(\textrm{mod}\, P)\\(a,\,P)=1}}\mathbf1_{d\mid a+2}=\frac1{\varphi(d)}\qquad(d\mid P).
	\end{equation*}
	For squarefree divisors supported on $\mathcal P_i$,
	\begin{equation*}
		\sum_{\substack{\mu^2(d)=1,\,\omega(d)=\ell\\p\mid d\Rightarrow p\in\mathcal P_i}}\frac1{\varphi(d)}\leqslant\frac1{\ell!}\biggl(\sum_{p\in\mathcal P_i}\frac1{p-1}\biggr)^\ell.
	\end{equation*}
	Since the prime sum on the right tends to $\log2<1$ and $V_i\gg1$, the corresponding tail satisfies
	\begin{equation*}
		\frac1{V_i}\sum_{\ell>R}\frac{\ell(1-\rho)^{\ell-1}}{\ell!}\biggl(\sum_{p\in\mathcal P_i}\frac1{p-1}\biggr)^\ell\leqslant\frac{e}{V_iR!}\ll\frac1{R!}.
	\end{equation*}
	Taking $R=0$ also bounds the full sum by an absolute constant. Applying these bounds to the expansion of $\mathcal F-\mathcal F_R$, with at least one $\ell_i>R$, gives
	\begin{equation*}
		\frac1{\varphi(P)}\sum_{\substack{a\,(\textrm{mod}\, P)\\(a,\,P)=1}}|\mathcal F(a+2)-\mathcal F_R(a+2)|\ll_{K,\,\rho}\frac1{R!}.
	\end{equation*}

	Now take $R=\lceil\log L\rceil$ and write $\mathcal F_R(n)=\sum_{d\mid n}c_d$. The disjointness of the prime sets gives a unique decomposition of each retained divisor into its factors supported on those sets. Consequently,
	\begin{equation*}
		d\leqslant\exp(4KRL^{0.2})=x^{o(1)},\qquad |c_d|\ll_{K,\,\rho}R^{2K}.
	\end{equation*}
	Every retained $d$ is squarefree and odd, so $d\mid p+2$ is the reduced residue class $p\equiv-2\,(\textrm{mod}\, d)$. The Bombieri--Vinogradov theorem, with sufficient logarithmic saving to absorb $R^{2K}$, gives
	\begin{equation*}
		\frac1x\sum_{x<p\leqslant2x}\log p\,\mathcal F_R(p+2)=\sum_d\frac{c_d}{\varphi(d)}+o(1).
	\end{equation*}
	The Chinese remainder theorem identifies the main term as
	\begin{equation*}
		\sum_d\frac{c_d}{\varphi(d)}=\frac1{\varphi(P)}\sum_{\substack{a\,(\textrm{mod}\, P)\\(a,\,P)=1}}\mathcal F_R(a+2).
	\end{equation*}

	Since $p+2\leqslant3x$ for $x<p\leqslant2x$ and sufficiently large $x$, the integer-average error is $O_{K,\,\rho}(L/R!)$ after multiplication by $\log p$ and division by $x$. Thus $L/R!\to0$ and the two remainder estimates give
	\begin{equation}\label{eq:rem-comparison}
		\frac1x\sum_{x<p\leqslant2x}\log p\,\mathcal F(p+2)=\frac1{\varphi(P)}\sum_{\substack{a\,(\textrm{mod}\, P)\\(a,\,P)=1}}\mathcal F(a+2)+o(1).
	\end{equation}

	By the definition of $m_j$ and the Chinese remainder theorem,
	\begin{equation*}
		\frac1{\varphi(P)}\sum_{\substack{a\,(\textrm{mod}\, P)\\(a,\,P)=1}}\mathcal W_j(a+2)=m_j.
	\end{equation*}
	For $j\ne k$, the prime sets defining the two weights are disjoint, so
	\begin{equation*}
		\frac1{\varphi(P)}\sum_{\substack{a\,(\textrm{mod}\, P)\\(a,\,P)=1}}\mathcal W_j(a+2)\mathcal W_k(a+2)=m_jm_k.
	\end{equation*}
	Combining these identities with \eqref{eq:rem-comparison}, together with the estimate $m_j\gg 1$, we deduce that for $j\ne k$
	\begin{equation*}
		\begin{aligned}
			\frac1x\sum_{x<p\leqslant2x}\log p\,\frac{\mathcal W_j(p+2)}{m_j}&=1+o(1),\\[1mm]
			\frac1x\sum_{x<p\leqslant2x}\log p\,\frac{\mathcal W_j(p+2)\mathcal W_k(p+2)}{m_jm_k}&=1+o(1).
		\end{aligned}
	\end{equation*}

	Moreover, $0\leqslant\mathcal W_j(n)\ll 1$ and $m_j\gg 1$ imply
	\begin{equation*}
		\biggl(\frac{\mathcal W_j(n)}{m_j}\biggr)^2\ll \frac{\mathcal W_j(n)}{m_j}.
	\end{equation*}
	The first-moment estimate therefore gives
	\begin{equation*}
		\frac1x\sum_{x<p\leqslant2x}\log p\biggl(\frac{\mathcal W_j(p+2)}{m_j}\biggr)^2\ll 1.
	\end{equation*}

	Finally, expanding the square and using the prime number theorem, we get
	\begin{equation*}
		\begin{aligned}
			\frac1x\sum_{x<p\leqslant2x}\log p\biggl(\frac1b\sum_{j=1}^{b}\frac{\mathcal W_j(p+2)}{m_j}-1\biggr)^2
			&=\frac1{b^2x}\sum_{j=1}^{b}\sum_{x<p\leqslant2x}\log p\biggl(\frac{\mathcal W_j(p+2)}{m_j}\biggr)^2-\frac1b+o(1)
			\\[1,2mm]
			&\leqslant\frac{C_{K,\,\rho}}b+o(1).
		\end{aligned}
	\end{equation*}
	This completes the proof of \eqref{eq:004}.

\label{prop:typeI}
Fix the weight $\mathcal W$ defined by \eqref{eq:mark} and let
$F(n)=\mu(n+2)\mathcal W(n+2)$. The first two terms in
Proposition~\ref{prop:vau} satisfy
\begin{equation}\label{eq:typeI}
\begin{aligned}
T_1(F),\,\ T_2(F)\ll_{A,\,K,\,\rho}\frac{x}{(\log x)^A}
\end{aligned}
\end{equation}
for any $A>0$.

First for $T_2$, let
\begin{equation*}
	\alpha_q=\sum_{\substack{u\ell=q\\u\leqslant U,\,\ell\leqslant V}}\mu(u)\Lambda(\ell),
\end{equation*}
whence $|\alpha_q|\leqslant\log q$. Since $UV=x^{2/5}$ and $R_Z(q)=R_Z(k)=1$ force $q,k$ to be odd, we have
\begin{equation*}
	T_2(F)=\sum_{\substack{q\leqslant x^{2/5}\\R_Z(q)=1}}\alpha_q\sum_{\substack{x<qk\leqslant2x\\2\nmid k}}R_Z(k)\mu(qk+2)\mathcal W(qk+2).
\end{equation*}
We first replace the two weights by finite divisor sums. The argument below uses only $|\alpha_q|\leqslant L$ and is uniform in the upper endpoint of the inner sum.

Fix $A>0$ and take $R=\lceil C\log L\rceil$, where $C$ is sufficiently large. For odd $k$, inclusion--exclusion gives
\begin{equation*}
	R_Z(k)=\sum_{\substack{r\mid k,\,\mu^2(r)=1\\p\mid r\Rightarrow2<p\leqslant Z\\\omega(r)\leqslant R}}\mu(r)+O\biggl(\sum_{\substack{r\mid k,\,\mu^2(r)=1\\p\mid r\Rightarrow2<p\leqslant Z\\\omega(r)=R+1}}1\biggr).
\end{equation*}
Every integer $r$ occurring in either sum above is a product of at most $R+1$ distinct primes in $(2,Z]$, so $r\leqslant Z^{R+1}=x^{o(1)}$.














Next, we truncate the divisor expansion of $\mathcal W$. To estimate the resulting error under the condition $r\mid k$, we employ the bound
\begin{equation*}
	\biggl|u\rho^{u-1}-\sum_{j=1}^R j(\rho-1)^{j-1}\binom uj\biggr|\leqslant(R+1)\binom u{R+1}\qquad(u\geqslant0).
\end{equation*}
Apply this bound to each factor of $\mathcal W$, expanding the difference of the products one factor at a time. Expanding the truncated factors in absolute value and bounding the untruncated factors gives finite divisor sums satisfying
\begin{equation*}
	\biggl|\mathcal W(n)-\sum_{d\mid n}c_d\biggr|\leqslant\sum_{d\mid n}e_d,\qquad e_d\geqslant0.
\end{equation*}
The coefficients are supported on squarefree $d$ whose prime factors belong to $\bigcup_i\mathcal P_i$, and
\begin{equation*}
	d\leqslant\exp\bigl(O_K(RL^{0.2})\bigr),\qquad \sum_d\frac{|c_d|}{d}\ll_{K,\,\rho}1,\qquad \sum_d(|c_d|+e_d)\leqslant\exp\bigl(O_{K,\,\rho}(RL^{0.2})\bigr)=x^{o(1)}.
\end{equation*}
The remainder has the stronger bound
\begin{equation*}
	\sum_d\frac{e_d}{d}\ll_{K,\,\rho}\sum_{i=1}^K\frac{V_i^{R+1}}{R!}\prod_{h<i}\biggl(\sum_{j=1}^R\frac{jV_h^j}{j!}\biggr)\ll_{K,\,\rho}\frac1{R!},
\end{equation*}
because $V_i=\log2+o(1)<1$. This follows by expanding the factor $\binom{\omega_i(n)}{R+1}$ in the remainder and the factors $\binom{\omega_h(n)}j$ preceding it.

For sufficiently large $x$, all prime factors of $d$ lie in $(2,Z]$. Thus $(q,\,d)=1$ whenever $R_Z(q)=1$. The conditions $r\mid k$ and $d\mid qk+2$ are incompatible if $(r,\,d)>1$; otherwise, together with oddness, they specify one residue class modulo $2rd$. Hence
\begin{equation*}
	\#\bigl\{k:\ x<qk\leqslant2x,\,2\nmid k,\,r\mid k,\,d\mid qk+2\bigr\}\ll\frac{x}{qrd}+1.
\end{equation*}

Moreover, the absolute coefficients of the truncated sieve satisfy
\begin{equation*}
	\sum_{\substack{\mu^2(r)=1\\p\mid r\Rightarrow2<p\leqslant Z\\\omega(r)\leqslant R}}\frac1r\leqslant\prod_{2<p\leqslant Z}\biggl(1+\frac1p\biggr)\ll\log Z.
\end{equation*}
We now estimate both truncation errors using the preceding counting bound, with $d=1$ for the remainder from $R_Z(k)$. In the next display, $r$ is squarefree and every prime factor of $r$ lies in $(2,Z]$. Since $\mathcal W(n)\ll_{K,\,\rho}1$, the total error is bounded, up to a factor depending only on $K$ and $\rho$, by
\begin{equation}\label{eq:bontail}
	\begin{aligned}
		\sum_{q\leqslant x^{2/5}}|
		&\alpha_q|\biggl\{\sum_{\omega(r)=R+1}\biggl(\frac{x}{qr}+1\biggr)+\sum_{\omega(r)\leqslant R}\sum_d e_d\biggl(\frac{x}{qrd}+1\biggr)\biggr\}\\
		&\ll xL^2\biggl\{\frac{\bigl(\sum_{p\leqslant Z}p^{-1}\bigr)^{R+1}}{(R+1)!}+\frac{\log Z}{R!}\biggr\}+x^{2/5+o(1)} \ll xL^{-A}.
	\end{aligned}
\end{equation}
The terms with $+1$ contribute $x^{2/5+o(1)}$, since $r\leqslant Z^{R+1}=x^{o(1)}$ and $\sum_d e_d=x^{o(1)}$.

To justify the last bound, use $\sum_{p\leqslant Z}p^{-1}\leqslant\log L$ for sufficiently large $x$ and $(R+1)!\geqslant((R+1)/e)^{R+1}$. For $C>e$ and $R=\lceil C\log L\rceil$, these inequalities give
\begin{equation*}
	\frac{\bigl(\sum_{p\leqslant Z}p^{-1}\bigr)^{R+1}}{(R+1)!}\leqslant\biggl(\frac eC\biggr)^{R+1}\leqslant L^{-C\log(C/e)}.
\end{equation*}
Choose $C$ so that $C\log(C/e)>A+2$. Moreover, $R!$ exceeds every fixed power of $L$ for sufficiently large $x$, which also gives $L^2\log Z/R!\ll_A L^{-A}$.
Therefore by the above argument, we obtain
\begin{equation*}
	\begin{aligned}
		T_2(F)&=\sum_{\substack{q\leqslant x^{2/5}\\R_Z(q)=1}}\alpha_q\sum_{\substack{\mu^2(r)=1\\p\mid r\Rightarrow2<p\leqslant Z\\\omega(r)\leqslant R}}\mu(r)\sum_{\substack{d\\(d,\,r)=1}}c_d
		\sum_{\substack{x<qk\leqslant2x\\2\nmid k\\r\mid k,\,d\mid qk+2}}\mu(qk+2)+O_{A,\,K,\,\rho}(xL^{-A}).
	\end{aligned}
\end{equation*}

We now estimate the remaining M\"obius sums, uniformly when the upper endpoint $2x$ is replaced by $y\in[x,\,2x]$. We first treat $T_2$; the same estimates will then give $T_1$ by partial summation.

Write $k=rj$. Since $d$ is odd, $d\mid qrj+2$ implies $(d,\,qr)=1$. For squarefree $d$, we have
\begin{equation}\label{eq:010}
	\mu(dv)=\mu(d)\mu(v)\mathbf1_{(v,\,d)=1}=\mu(d)\sum_{\substack{a\mid v,\, p\mid a\Rightarrow p\mid d}}\mu(v/a).
\end{equation}
Here $a$ may contain higher prime powers: for each prime dividing both $d$ and $v$, the two nonzero local terms in the sum are $1$ and $-1$.

Substituting $qrj+2=dat$ therefore gives
\begin{equation*}
	\begin{aligned}
		&\sum_{\substack{x<qrj\leqslant y\\2\nmid j,\,d\mid qrj+2}}\mu(qrj+2)=\mu(d)\sum_{\substack{a\geqslant1\\p\mid a\Rightarrow p\mid d}}\ \sum_{\substack{(x+2)/(da)<t\leqslant(y+2)/(da)\\dat\equiv qr+2\,(\textrm{mod}\,2qr)}}\mu(t).
	\end{aligned}
\end{equation*}
The congruence is equivalent to $j$ being odd. Moreover, $(da,\,2qr)=(qr+2,\,2qr)=1$, so the inner sum runs over a reduced residue class modulo $2qr$. We estimate it separately according as $da\leqslant x^{1/20}$ or $da>x^{1/20}$.

First suppose that $da\leqslant x^{1/20}$ and take $Y=(2x+2)/(da)$. Since $qr\leqslant x^{2/5}Z^R=x^{2/5+o(1)}$, we have
\begin{equation*}
	Y\geqslant2x^{19/20},\qquad \frac{2qr}{Y^{1/2}}\ll x^{-3/40+o(1)}.
\end{equation*}
Thus the modulus $2qr$ satisfies $2qr\leqslant Y^{1/2}L^{-B}$ for any fixed $B>0$, as required in \eqref{BV-mobius}.

For fixed $d$ and $a$, group the terms with the same product $qr$. There are at most $\tau(qr)$ such pairs, and $|\alpha_q\mu(r)|\leqslant L$, so the combined coefficient has absolute value at most $L\tau(qr)$. We therefore need to include the factor $\tau(qr)$ in the Bombieri--Vinogradov estimate. Let
\begin{equation*}
	E(Y;m):=\max_{(c,\,m)=1}\max_{ z\leqslant Y}
	\biggl|\sum_{\substack{t\leqslant z\\t\equiv c\,(\textrm{mod}\,m)}}\mu(t)\biggr|,
\end{equation*}
and hence $E(Y;m)\ll Y/m+1$ trivially. By applying \eqref{BV-mobius}, together with Cauchy's inequality, we deduce that
\begin{equation*}\label{eq:wtbv}
	\begin{aligned}
		\biggl(\sum_{m\leqslant Q}\tau(m)E(Y;m)\biggr)^2&\leqslant\biggl(\sum_{m\leqslant Q}E(Y;m)\biggr)\biggl(\sum_{m\leqslant Q}\tau(m)^2E(Y;m)\biggr)\\
		&\ll YL^{-A_0}\biggl(Y\sum_{m\leqslant Q}\frac{\tau(m)^2}{m}+\sum_{m\leqslant Q}\tau(m)^2\biggr)\\
		&\ll Y^2L^{-A_0+4}.
	\end{aligned}
\end{equation*}
for any $Q\leqslant Y^{1/2}L^{-B}$. Taking $A_0>2A+4$, one finds
\begin{equation*}
	\sum_{m\leqslant Q}\tau(m)E(Y;m)\ll_A YL^{-A}.
\end{equation*}

Since $(da,\,2qr)=(qr+2,\,2qr)=1$, the definition of $E$ gives, for $x\leqslant y\leqslant2x$ and $Y=(2x+2)/(da)$,
\begin{equation*}
	\biggl|\sum_{\substack{(x+2)/(da)<t\leqslant(y+2)/(da)\\dat\equiv qr+2\,(\textrm{mod}\,2qr)}}\mu(t)\biggr|\leqslant2E(Y;2qr).
\end{equation*} 
After taking absolute values, enlarge the ranges of $q$ and $r$ to $q\leqslant x^{2/5}$ and $r\leqslant Z^R$. Grouping terms with the same product $qr$ and applying the weighted estimate with $A+1$ in place of $A$ gives
\begin{equation*}
	\begin{aligned}
		2\sum_d|c_d|\sum_{\substack{a\geqslant1,\,da\leqslant x^{1/20}\\p\mid a\Rightarrow p\mid d}}\sum_{\substack{q\leqslant x^{2/5}\\r\leqslant Z^R}}|\alpha_q|E\biggl(\frac{2x+2}{da};2qr\biggr)
		\ll xL^{-A}\sum_d\frac{|c_d|}{d}\sum_{\substack{a\geqslant1\\p\mid a\Rightarrow p\mid d}}\frac1a\ll xL^{-A},
	\end{aligned}
\end{equation*}
where the last inequality uses $\sum_d|c_d|/d\ll 1$ and
\begin{equation*}
	\sum_{\substack{a\geqslant1\\p\mid a\Rightarrow p\mid d}}\frac1a=\prod_{p\mid d}(1-p^{-1})^{-1}\ll1.
\end{equation*}

It remains to treat $da>x^{1/20}$. Since $d=x^{o(1)}$, we have $a>x^{1/25}$ for sufficiently large $x$. Rankin's inequalities give
\begin{equation}\label{eq:supptl}
	\begin{aligned}
		\sum_{\substack{a>x^{1/25}\\p\mid a\Rightarrow p\mid d}}\frac1a&\leqslant x^{-1/50}\prod_{p\mid d}(1-p^{-1/2})^{-1}\ll x^{-1/50},\\
		\sum_{\substack{a\leqslant3x\\p\mid a\Rightarrow p\mid d}}1&\leqslant(3x)^{1/20}\prod_{p\mid d}(1-p^{-1/20})^{-1}\ll x^{1/20}.
	\end{aligned}
\end{equation}
Both products are $1+o(1)$ uniformly in $d$, since $\omega(d)=O_K(\log L)$ and every prime dividing $d$ exceeds $\exp(L^{0.1})$.

The progression contains $O(x/(daqr)+1)$ terms and is empty when $da>3x$. In the following sums, $r$ runs over the squarefree integers satisfying $\omega(r)\leqslant R$ and $p\mid r\Rightarrow2<p\leqslant Z$. The absolute contribution from $da>x^{1/20}$ is bounded by 
\begin{equation*}
	\begin{aligned}
		\sum_{q\leqslant x^{2/5}}|\alpha_q|
		\sum_r\sum_d|c_d|\sum_{\substack{x^{\frac{1}{20}}<da\leqslant3x\\p\mid a\Rightarrow p\mid d}}\biggl(\frac{x}{daqr}+1\biggr)
		\ll x^{\frac{49}{50}}L^2\biggl(\sum_r\frac1r\biggr)\sum_d\frac{|c_d|}{d}+x^{9/20+o(1)}\ll xL^{-A},
	\end{aligned}
\end{equation*}
where we have used \eqref{eq:supptl}. Here $\sum_r1/r\ll\log Z$, $\sum_r1\leqslant Z^R=x^{o(1)}$, and $\sum_d|c_d|=x^{o(1)}$. Together with the truncation errors, this proves $T_2(F)\ll_{A,\,K,\,\rho}xL^{-A}$, uniformly in the upper endpoint $y$.

Finally, for $T_1$, use $\log k=\log(qk)-\log q$. Partial summation handles $\log(qk)$ with $\alpha_q=\mu(q)\mathbf1_{q\leqslant U}$; the term involving $\log q$ uses the same estimate with $\alpha_q=\mu(q)\log q\,\mathbf1_{q\leqslant U}$.

Both choices satisfy $|\alpha_q|\leqslant L$. Applying the preceding bounds with $A+1$ in place of $A$ absorbs the factor $O(L)$ from partial summation and gives
\begin{equation*}
	|T_1(F)|+|T_2(F)|\ll_{A,\,K,\,\rho}xL^{-A},
\end{equation*}
which completes the proof of Proposition \ref{prop:typeI}.

\label{lem:shared}
In \eqref{eq:013}, the total absolute contribution of terms for which $a,b$ share a prime is
$O_{A,K}(XYL^{-A})$, for every fixed $A>0$.

We first show that, for every odd $\ell\asymp Y=x^{o(1)}$,
\begin{equation}\label{eq:014}
\begin{aligned}
\sum_{\substack{h\ll X/Y\\\ell h>2}}\tau(\ell h-2)^2
 \ll(X/Y)L^3.
\end{aligned}
\end{equation}
Use $\tau^2\leqslant\tau_4$ and delete a largest factor from each ordered
four-factor decomposition. The remaining product satisfies
$d\ll X^{3/4}$, with at most $4\tau_3(d)$ choices.

If $d\mid\ell h-2$, then $(d,\ell)\mid2$.
Since $\ell$ is odd, $(d,\ell)=1$. Thus
\begin{equation*}
\begin{aligned}
\sum_{d\ll X^{3/4}}4\tau_3(d)\biggl(\frac{X}{Yd}+1\biggr)
 \ll(X/Y)L^3+X^{3/4}L^2\ll(X/Y)L^3.
\end{aligned}
\end{equation*}
For fixed $a,\,b$, let $C_1>0$ depend only on the original
coefficient-size exponent, not on $K$. Cauchy's inequality and
\eqref{eq:014} bound the absolute coefficient sum over the common
quotient $h$ by $O((X/Y)L^{C_1})$.
The number of product pairs sharing a prime in $\bigcup_i\mathcal P_i$ is at most
\begin{equation}\label{eq:abcoll}
\begin{aligned}
C_{K,\,\rho}Y^2\sum_{p\in\cup_i\mathcal P_i}p^{-2}
 \ll_{K,\,\rho}Y^2e^{-cL^{0.1}}.
\end{aligned}
\end{equation}
Combining \eqref{eq:014} with \eqref{eq:abcoll} proves the assertion, including the case $a=b$.

\label{prop:D}
Fix $\delta,C,A>0$, and let $M,N\geqslant x^\delta$ with $MN\asymp x$.
Suppose that $\alpha,\beta$ are supported on sifted integers in
subintervals of their dyadic intervals, with
$|\alpha_m|,|\beta_n|\leqslant L^C$.
First choose $A_0$ sufficiently large, and then choose a sufficiently
large fixed $K$. These choices give
\begin{equation*}
\begin{aligned}
|Q_Y-Q_Y^{\mathrm{maj}}|\ll_A XYL^{-A}.
\end{aligned}
\end{equation*}
The choices of $A_0,K$ do not depend on the fixed exponents $a_i$.

\label{prop:parity-conjugacy}
	The map $T$ gives a bijection between $\Omega\cap\mathcal C$ and the primitive integer vectors in $\Omega'$ with odd first coordinate. For functions $f,\,g$ on the states with positions in $\Omega\cap\mathcal C$, define $\mathcal U_Tf$ on the transformed states by
	\begin{equation}\label{eq:utdef}
		(\mathcal U_Tf)(TP,\,\boldsymbol p)=f(P,\,\boldsymbol p),\qquad \langle\mathcal U_Tf,\,\mathcal U_Tg\rangle=\langle f,\,g\rangle.
	\end{equation}
	Then $\mathcal U_T$ is unitary for the state measures $\sigma$ and satisfies
	\begin{equation}\label{eq:conj}
		\mathcal U_T\mathcal A_{-2}^{\mathcal C}\mathcal U_T^{-1}=\mathcal A_1^{\Omega',\,\mathrm{odd}}.
	\end{equation}
	For $P\in\Omega\cap\mathcal C$, let $u_{TP}$ be the indicator of states with position $TP$ in the transformed state space. Then
	\begin{equation*}
		\langle u_P,\,(\mathcal A_{-2}^{\mathcal C}(\mathcal A_{-2}^{\mathcal C})^*)^Ru_P\rangle=\langle u_{TP},\,(\mathcal A_1^{\Omega',\,\mathrm{odd}}(\mathcal A_1^{\Omega',\,\mathrm{odd}})^*)^Ru_{TP}\rangle.
	\end{equation*}

For integers $u,\,v$ with $u$ odd,
	\begin{equation}\label{eq:gcdpar}
		(u,\,u-2v)=(u,\,v).
	\end{equation}
	Thus $T$ and $T^{-1}$ preserve primitivity on the stated sets and give the required bijection. Since $T$ leaves the first coordinate and every list unchanged, it also preserves admissibility and the state measure $\sigma$, proving \eqref{eq:utdef}.

	We next check the determinant and major-arc factors. For every allowed transition between $P,\,Q\in\mathcal C$, the odd integer $D$ divides both first coordinates. Hence $t=\det(P,\,Q)/D$ is an even integer, and
	\begin{equation}\label{eq:detconj}
		t':=\frac{\det(TP,\,TQ)}D=-\frac12\frac{\det(P,\,Q)}D=-\frac t2.
	\end{equation}
	Hence $t=-2(b-a)$ is equivalent to $t'=b-a$, and $\psi_{-2}(t/Y)=\psi_1(t'/Y)$. The change of variables $\phi=-2\theta$ on $\mathbb T$ gives
	\begin{equation}\label{eq:019}
		\int_{\mathfrak M_{-2}}e\bigl(\theta(t+2b-2a)\bigr)\,\mathrm d\theta=\int_{\mathfrak M_1}e\bigl(\phi(t'-b+a)\bigr)\,\mathrm d\phi.
	\end{equation}
	There is no additional factor: the two inverse branches each have Jacobian $1/2$. All other kernel factors depend only on the unchanged first coordinates and prime lists, so the operators before the good-state restrictions agree under $\mathcal U_T$.

	Finally, for $P=(u,\,v)^T\in\Omega\cap\mathcal C$, choose $c,\,d\in\mathbb Z$ with $ud-vc=1$. The vector $(-2c,\,d-c)^T$ is an integral complement to $TP$, so
	\begin{equation}\label{eq:022}
		r_{TP}\equiv-2r_P\,(\textrm{mod}\,1).
	\end{equation}
	The good-state conditions at $TP$ are exactly those defining $\mathcal G_{-2}$ at $P$. Their exceptional-ratio bound is unchanged because multiplication by $-2$ preserves normalized measure on $\mathbb T$.

	List symmetrization is also unchanged, proving \eqref{eq:conj}. The moment identity follows from unitarity and $\mathcal U_Tu_P=u_{TP}$.

Write $s=u/(d_0YM)$ and $t_0=v/N$. For every fixed $A>0$,
	\begin{equation*}
		\begin{aligned}
			&\frac1{d_0YMN}\sum_{P\in\Omega\cap\mathcal C}\bigl\langle u_P,\,\bigl(\mathcal A_{-2}^{\mathcal C}(\mathcal A_{-2}^{\mathcal C})^*\bigr)^Ru_P\bigr\rangle\\
			&\qquad=\frac1{3\zeta(2)}\int_1^{16}\int_1^2\int_0^1\mathcal M_R(d_0YM s,\,Nt_0,\,r)\,\mathrm dr\,\mathrm dt_0\,\mathrm ds+O_A(L^{-2AR}).
		\end{aligned}
	\end{equation*}
	The same replacement applies separately to the absolute sums for the two terms in braces in $K_1(P,\,Q;D,\,a,\,b)$, after the endpoint coefficients are bounded by their suprema. Either endpoint may be required to fail goodness; the normalized error in these one-edge cases is $O_A(L^{-A})$.

We first establish the replacement when only finitely many prime residues are prescribed. Let $S$ be odd and squarefree with $S\leqslant\exp(O_K(L^{0.98}))$, and prescribe a line $\ell_p\in\mathbb P^1(\mathbb F_p)$ for each $p\mid S$. Let $I_1,\,I_2,\,I_3$ be intervals in $[1,\,16]$, $[1,\,2]$, and $[0,\,1]$, respectively.

	We shall apply Lemma~\ref{lem:app-root-count} established in Appendix \ref{Append} with modulus $2S$. Exactly two of the six matrices in $\mathrm{SL}_2(\mathbb F_2)$ have first column $(1,\,1)^T$. At every odd prime, $g\mapsto TgE$ is a bijection of $\mathrm{SL}_2(\mathbb F_p)$, and its first-row kernel is uniform on $\mathbb P^1(\mathbb F_p)$. The Chinese remainder theorem therefore gives, for some $c_\delta>0$,
	\begin{equation*}
		\begin{aligned}
			&\frac1{d_0YMN}\#\biggl\{P=(u,\,v)^T\in\Omega\cap\mathcal C:\ \frac{u}{d_0YM}\in I_1,\ \frac vN\in I_2,\ \frac cu\in I_3,\ \ell_p(g')=\ell_p\ (p\mid S)\biggr\}\\
			&\qquad=\frac{|I_1||I_2||I_3|}{3\zeta(2)\prod_{p\mid S}(p+1)}+O\bigl(x^{-c_\delta+o(1)}\bigr).
		\end{aligned}
	\end{equation*}
	The error is uniform in the intervals and the prescribed lines. Thus the measure for the original root coordinates is
	\begin{equation}\label{eq:density}
		\begin{aligned}
			\frac1{3\zeta(2)}\,\mathrm{d}(u/(d_0YM))\,\mathrm{d}(v/N)\,\mathrm{d}r,
		\end{aligned}
	\end{equation}
	and each prescribed odd-prime line contributes the factor $1/(p+1)$.

	We next bound the relative positions and the number of terms to which this count is applied. For consecutive original positions $P_j=(u_j,\,v_j)^T$ on a path, the kernel support gives
	\begin{equation*}
		|\det(P_j,\,P_{j+1})|\ll d_0Y,\qquad \biggl|\frac{v_{j+1}}{u_{j+1}}-\frac{v_j}{u_j}\biggr|\ll\frac1{d_0YM^2}.
	\end{equation*}
	Since $P_j=gEz_j$ and $P_0=P$, summing over at most $2R$ edges gives
	\begin{equation*}
		2|(z_j)_2|=|\det(P,\,P_j)|\ll Rd_0Y,\qquad |(z_j)_1|=|\tau(z_j)+2r(z_j)_2|\ll Rd_0Y.
	\end{equation*}
	Here $1/16\leqslant\tau(z_j)\leqslant16$ follows from the first-coordinate restriction. We sum over the vectors $(z_0,\,\ldots,\,z_{2R})$, the $K$ ordered prime tuples $\boldsymbol p_i$ at each $g'z_j$, and all permutations of their $J+1$ coordinates. We bound the sum of the absolute coefficients attached to these choices by $\exp(O_K(L^{0.73}))$, since
	\begin{equation*}
		R\log(Rd_0Y)+KR(J+1)L^{0.2}+KR(J+1)\log(J+1)\ll_K L^{0.73}.
	\end{equation*}

	Keep the exact factors of every prime occurring in a prime list for some $0\leqslant j\leqslant2R$. For each remaining prime $p$, its damping factor lies in $[0,\,1]$ and differs from $1$ only if $\ell_p=[z_j]_p$ for some $j$. Its mean deficit is therefore at most $(2R+1)/(p+1)$.

	Put $B=\lceil L^{0.76}\rceil$ and bound the product of these damping factors between the consecutive Bonferroni polynomials of degrees $B-1$ and $B$. Their mean difference is bounded by
	\begin{equation*}
		(2R+1)^B\sum_{\substack{p_1<\cdots<p_B\\p_\nu\in\bigcup_i\mathcal P_i}}\frac1{(p_1+1)\cdots(p_B+1)}\leqslant\frac{(C_K(2R+1))^B}{B!}\leqslant\exp(-cL^{0.76}\log L)
	\end{equation*}
	for some $c>0$, using $B!\geqslant(B/e)^B$ and $2R\asymp L^{1/2}$. This bound absorbs the preceding absolute coefficient mass. Every retained term involves a squarefree modulus satisfying
	\begin{equation*}
		\log S\ll_K R(J+1)L^{0.2}+BL^{0.2}\ll_K L^{0.96}.
	\end{equation*}
	For each retained prime, evaluate its local factor directly as a function of its single line $\ell_p$. The total number of retained terms and residue choices is $\exp(o(L))$. Apply the finite-residue count to both Bonferroni bounds for each path and list choice, using the absolute path coefficients to bound the error. It remains to justify imposing the position and good-state conditions in this count.

	For $z=(z_1,\,z_2)^T$, direct multiplication gives
	\begin{equation*}
		\begin{aligned}
			(g'z)_1&=u\tau(z),\quad
			(g'z)_1-2(g'z)_2&=v\tau(z)-\frac{2z_2}{u}.
		\end{aligned}
	\end{equation*}
	Thus, in the normalized coordinates $s=u/(d_0YM)$ and $t_0=v/N$, the boundary equations of $g'z\in\Omega'$ are
	\begin{equation}\label{eq:faces}
		\begin{aligned}
			s\tau(z)\in\{1,\,16\},\qquad t_0\tau(z)-\frac{2z_2}{d_0YMN s}\in\{1,\,2\}.
		\end{aligned}
	\end{equation}
	The derivatives of the two expressions with respect to $s$ and $t_0$, respectively, equal $\tau(z)\in[1/16,\,16]$. Their other first derivatives are $\exp(o(L))$, since $|z|\ll Rd_0Y$ and $\log(d_0Y)=O_K(L^{0.21})$. In particular,
	\begin{equation*}
		\frac{|z_2|}{d_0YMN}\ll\frac R{MN},
	\end{equation*}
	so the normalized boundary estimates introduce no factor $d_0YM/N$.

	For the complement $w$ of $z$ chosen above, the good-state ratio satisfies
	\begin{equation}\label{eq:rderiv}
		\begin{aligned}
			r_{g'z}\equiv\frac{\tau(w)}{\tau(z)}\,(\textrm{mod}\,1),\qquad \frac{\partial}{\partial r}\frac{\tau(w)}{\tau(z)}=-\frac{2}{\tau(z)^2}.
		\end{aligned}
	\end{equation}
	Its derivative has fixed sign and modulus bounded away from zero. The prime choices and integer translates occurring in the two good-state tests give only $\exp(o(L))$ boundary values of $r$. The weighted exceptional-choice condition is constant between these values, so the same assertion holds when goodness is replaced by its failure.

	Partition $[1,\,16]\times[1,\,2]\times[0,\,1]$ into cubes of side $x^{-c_\delta/8}$. There are $O(x^{3c_\delta/8})$ cubes. The union of cubes meeting a position boundary or a good-state boundary has volume at most $x^{-c_\delta/8+o(1)}$; on every remaining cube all these indicators are constant.

	Let $\mathcal E_{\mathrm{count}}$ be the total absolute counting error over the retained terms and cubes, and let $\mathcal E_{\partial}$ be the corresponding absolute main mass of the boundary cubes. Including all discrete choices in the factors $x^{o(1)}$, we obtain
	\begin{equation}\label{eq:root-grid-errors}
		\begin{aligned}
			\mathcal E_{\mathrm{count}}\ll d_0YMN x^{-5c_\delta/8+o(1)},\qquad \mathcal E_{\partial}\ll d_0YMN x^{-c_\delta/8+o(1)}.
		\end{aligned}
	\end{equation}
	The discrepancy on the boundary cubes is already included in $\mathcal E_{\mathrm{count}}$. Since $R\asymp L^{1/2}$, the total normalized error satisfies
	\begin{equation*}
		\frac{\mathcal E_{\mathrm{count}}+\mathcal E_{\partial}}{d_0YMN}+\exp\bigl(C_KL^{0.73}-cL^{0.76}\log L\bigr)\ll_A L^{-2AR}.
	\end{equation*}
	Together with the conjugacy identity \eqref{eq:conj}, this proves the asserted moment replacement.

	For one edge, use $|z|\ll d_0Y$ and omit the condition that the final position equals the initial one. After bounding the endpoint coefficients by their suprema, the absolute values of the two kernel terms have the same finite-residue and boundary properties. Failure of goodness at either endpoint replaces an indicator by its complement. The same proof therefore gives normalized error $O_A(L^{-A})$ in all the stated one-edge cases.

\label{prop:par}
	Fix $E_0,\delta>0$ and suppose $M,N\geqslant x^\delta$, $MN\asymp x$. Choosing $A_0$ sufficiently large and then a sufficiently large fixed $K$, independently of the particular exponents $a_i$, gives
	\begin{equation}\label{eq:moment}
		\frac1{d_0YMN}\sum_{P\in\Omega\cap\mathcal C}\bigl\langle u_P,\,\bigl(\mathcal A_{-2}^{\mathcal C}(\mathcal A_{-2}^{\mathcal C})^*\bigr)^Ru_P\bigr\rangle\ll L^{-2RE_0}.
	\end{equation}
	The one-edge root-replacement conclusion of Subsection~\ref{sec:roots}, including either endpoint failing its good-state tests, holds with the same normalization and error $O_A(L^{-A})$.

Take $G=E_0+5$ and fix $A_0,K$ so that \eqref{eq:esmall} holds; $C_*$ in \eqref{eq:crudebd} is now fixed. We first estimate the error caused by restricting the total number of pairs in $\mathfrak m$ to $\lceil L^2\rceil$.

	We expand the matrix element using the definitions of $G_j$ and $E_j$ without the restriction $\sum_i k_i\leqslant \lceil L^2\rceil$, writing
\begin{equation*}
\langle b,\,G_0E_0G_1\cdots E_{2R-1}G_{2R}b\rangle_{\mathrm{distinct}}=\sum_\gamma c_\gamma.
\end{equation*}
We let $\gamma$ specify all vectors, prime tuples, permutations, and coordinate choices in the defining sums for $G_j$ and $E_j$, subject to the stated distinctness conditions; $c_\gamma$ includes all measure weights and factorial factors. We write $k_i^{(t)}(\gamma)$ for the number of coordinates of $\mathfrak m_i$ after the first $t$ factors, counted from the left, and define
\begin{equation*}
\mathcal E_{\mathrm{mem}}=\biggl(\prod_p b'_p\biggr)\sum_\gamma|c_\gamma|\mathbf1_{\max_{0\leqslant t\leqslant4R+1}\sum_{i=1}^K k_i^{(t)}(\gamma)>\lceil L^2\rceil}.
\end{equation*}
The $2R$ operators $E_j$ append at most $2KR$ coordinates in total, so every term counted in $\mathcal E_{\mathrm{mem}}$ has at least $\lceil L^2\rceil-2KR$ coordinates appended by the operators $G_j$. We multiply $|c_\gamma|$ by $2$ for each coordinate appended by an operator $G_j$.

	For a prime $p\in\mathcal P_i$ that occurs in none of the prime tuples at $z_0,\,\ldots,\,z_{2R}$, we have $A_p=\varnothing$. We sum over the indices $0\leqslant a<c\leqslant2R$ for which $G_a$ appends the coordinate $(p,\,[z_a]_p)$ to $\mathfrak m_i$ and $G_c$ removes that coordinate. We retain this coordinate between those two factors with the inserted factor $2$, getting
	\begin{equation*}
		\begin{aligned}
		\frac2{(p+1)b'_p}\sum_{0\leqslant a<c\leqslant2R}\eta'_a\eta'_c\mathbf1_{[z_a]_p=[z_c]_p}
		\prod_{a<j<c}\Bigl(1-\eta'_j\mathbf1_{[z_j]_p=[z_a]_p}\Bigr)\leqslant\frac{2(2R+1)}{(p+1)b'_p}\ll\frac Rp.
		\end{aligned}
	\end{equation*}
	Indeed, for fixed $a$, the sum over $c$ telescopes to at most $1$. Enlarging the product to all primes in $\bigcup_i\mathcal P_i$, their total factor is bounded by
	\begin{equation*}
		\prod_{p\in\bigcup_i\mathcal P_i}\biggl(1+\frac{C_\rho R}p\biggr)\leqslant\exp\biggl(C_\rho R\sum_{p\in\bigcup_i\mathcal P_i}\frac1p\biggr)\leqslant\exp(C_{K,\,\rho}R).
	\end{equation*}
	There are $O_K(J+R)$ primes appearing in active lists, each with at most $(2R+2)^2$ choices of the indices at which $G_j$ adds or removes its pair. Combining these factors with the path and list bound in Subsection~\ref{sec:roots}, and removing the inserted factors from the discarded terms, gives
	\begin{equation}\label{eq:memtail}
		\begin{aligned}
			\mathcal E_{\mathrm{mem}}&\leqslant2^{-\lceil L^2\rceil+2KR}\exp\bigl(O_{K,\,\rho}(L^{0.73}+(J+R)\log(2R+2)+R)\bigr)\\
			&\ll2^{-\lceil L^2\rceil+2KR}\exp(O_{K,\,\rho}(L^{0.74}))\ll_A L^{-2AR}.
		\end{aligned}
	\end{equation}

	Under the restriction $\sum_i k_i\leqslant \lceil L^2\rceil$, let $\mathcal B$ index the initial list entries, the unshared list coordinate in each group for each $E_j$, and the first $\lceil L^2\rceil$ coordinates of the tuple added by each $G_j$ in each group. Order the initial indices first and the others according to the product $G_0E_0G_1\cdots E_{2R-1}G_{2R}$, with a fixed order within each factor. Then
	\begin{equation}\label{eq:birthct}
		|\mathcal B|\leqslant K(J+1)+2KR+K(2R+1)\lceil L^2\rceil\leqslant L^{O_K(1)}.
	\end{equation}
	For each term in the expansion, let $\mathcal B_{\mathrm{act}}\subseteq\mathcal B$ consist of the initial indices, the indices where $E_j$ selects a prime without taking it from $\mathfrak m$, and the indices of the coordinates actually added by $G_j$. Write $p_a$ for the prime selected at $a\in\mathcal B_{\mathrm{act}}$. Thus transferring an existing pair from $\mathfrak m$ to a list introduces no new index in $\mathcal B_{\mathrm{act}}$. Let $\mathcal C_0$ range over collections of disjoint subsets $C\subseteq\mathcal B$ with $|C|\geqslant2$, and let $E_C$ mean that $C\subseteq\mathcal B_{\mathrm{act}}$ and $p_a=p_{a'}$ for all $a,\,a'\in C$. Then
	\begin{equation}\label{eq:025}
		\prod_{\substack{a,\,a'\in\mathcal B_{\mathrm{act}}\\a<a'}}\mathbf1_{p_a\ne p_{a'}}=\sum_{\mathcal C_0}\prod_{C\in\mathcal C_0}(-1)^{|C|-1}(|C|-1)!\prod_{C\in\mathcal C_0}\mathbf1_{E_C}.
	\end{equation}
	Indeed, on the indices $a\in\mathcal B_{\mathrm{act}}$ having one common prime value, the right side is the sum of permutation signs: a cycle on $l$ specified indices has $(l-1)!$ orderings and sign $(-1)^{l-1}$. This sum is $1$ for a singleton and $0$ otherwise.

	For each collection define its rank by $r(\mathcal C_0)=\sum_{C\in\mathcal C_0}(|C|-1)$. It involves at most $2r(\mathcal C_0)$ indices, and
	\begin{equation}\label{eq:rankdef}
		\sum_{r(\mathcal C_0)=r}\prod_{C\in\mathcal C_0}(|C|-1)!\leqslant |\mathcal B|^{2r}.
	\end{equation}
	To obtain this bound, decompose each counted permutation canonically into $r$ transpositions; the ordered list of pairs of indices determines the permutation. Define
	\begin{equation*}
		\mathcal I(\mathcal C_0)=\bigl\langle b,\,G_0E_0G_1\cdots E_{2R-1}G_{2R}b\bigr\rangle_{\bigcap_{C\in\mathcal C_0}E_C},
	\end{equation*}
	where we retain only terms satisfying all the conditions $E_C$ and $\sum_i k_i\leqslant \lceil L^2\rceil$ after each factor $G_j$ or $E_j$.

	For large rank, sum the prime choices in the specified order. In each $C$, leave the first choice unrestricted; each of the other $|C|-1$ choices then has a prescribed value. Let $R_{\mathrm{fix},s}(E_j)$ be the weighted absolute row bound when $s$ specified primes selected by $E_j$, without being taken from $\mathfrak m$, have prescribed values. The count in \eqref{eq:target} retains the corresponding factors $\nu_i(p)\leqslant\Delta$ and gives
	\begin{equation}\label{eq:eatom}
		R_{\mathrm{fix},s}(E_j)\ll_{K,\,\rho}\lceil L^2\rceil^K(1+L^{3A_0})\Delta^s\qquad(0\leqslant s\leqslant K).
	\end{equation}
	For the group-$i$ part $G_{j,i}$ of $G_j$, define $R_{\mathrm{fix},s}(G_{j,i})$ similarly by prescribing $s$ ordered coordinates of the new tuple. The factor from removing or retaining the existing pairs is at most $1$, so
	\begin{equation}\label{eq:gatom}
		R_{\mathrm{fix},s}(G_{j,i})\leqslant\sum_{l\geqslant s}\frac{(v_0\eta'_jV_i/\vartheta)^l\Delta^s s_i^{l-s}}{l!}\ll_{K,\,\rho}(C_{K,\,\rho}\Delta)^s.
	\end{equation}
	This follows from $1/l!\leqslant1/(l-s)!$; requiring the tuple length to reach a specified index only decreases the sum in \eqref{eq:gatom}. Initial entries have the same factor $\Delta$. These bounds are uniform in all previously selected values, including earlier coordinates of the same tuple.

	We omit the condition $z_{2R}=z_0$ and iterate the absolute row bounds, using $b\leqslant w$. We absorb the bounds for the two occurrences of $b$ in $\mathcal I(\mathcal C_0)$ and for all $G_j$ into a fixed enlargement of $C_*$. We obtain
	\begin{equation*}
		|\mathcal I(\mathcal C_0)|\leqslant L^{C_*(2R+1)}(C_{K,\,\rho}\Delta)^{r(\mathcal C_0)}.
	\end{equation*}
	Choose $C_0>2(C_*+E_0+7)$ and put
	\begin{equation}\label{eq:rankcut}
		r_0=\biggl\lceil C_0\frac{2R\log L}{L^{0.1}}\biggr\rceil,\qquad \frac{r_0}{2R}=O\biggl(\frac{\log L}{L^{0.1}}\biggr)=o(1).
	\end{equation}
	Since $C_{K,\,\rho}|\mathcal B|^2\Delta\leqslant e^{-L^{0.1}/2}$ for large $x$, the high-rank contribution satisfies
	\begin{equation}\label{eq:hirank}
		\begin{aligned}
			&\sum_{r(\mathcal C_0)\geqslant r_0}\prod_{C\in\mathcal C_0}(|C|-1)!\,|\mathcal I(\mathcal C_0)|\leqslant L^{C_*(2R+1)}\sum_{r\geqslant r_0}(C_{K,\,\rho}|\mathcal B|^2\Delta)^r\ll L^{-2R(E_0+4)}.
		\end{aligned}
	\end{equation}

	For $r<r_0$, retain the signed estimate \eqref{eq:esmall} for each $E_j$ unaffected by the equality constraints. Write $C=\{a_0,\,\ldots,\,a_s\}$, with $a_0$ its first index in the specified order. Orthogonality on $\mathbb T$ gives
	\begin{equation}\label{eq:orth}
		\mathbf1_{E_C}=\begin{cases}\displaystyle\int_{\mathbb T^s}e\biggl(\sum_{h=1}^s\theta_h(p_{a_h}-p_{a_0})\biggr)\,\mathrm d\boldsymbol\theta,&C\subseteq\mathcal B_{\mathrm{act}},\\0,&C\not\subseteq\mathcal B_{\mathrm{act}}.\end{cases}
	\end{equation}
	When $C\subseteq\mathcal B_{\mathrm{act}}$, we factor the exponential in \eqref{eq:orth} as follows; we call the individual exponentials on the right-hand side its phase factors:
	\begin{equation*}
		e\biggl(\sum_{h=1}^s\theta_h(p_{a_h}-p_{a_0})\biggr)=e\biggl(-p_{a_0}\sum_{h=1}^s\theta_h\biggr)\prod_{h=1}^s e(\theta_hp_{a_h}).
	\end{equation*}
	Thus each phase factor multiplies only the initial entry or the operator $E_j$ or $G_j$ at which its prime is selected.

	For an ordered tuple $\mathbf p=(p_1,\,\ldots,\,p_l)\in\mathcal P_i^l$ appended by $G_j$, we define $\Phi_l(\mathbf p)$ as the product, over all $C\in\mathcal C_0$, of those factors $e(-p_{a_0}\sum_{h=1}^s\theta_h)$ and $e(\theta_hp_{a_h})$ in the preceding factorization whose selection indices refer to coordinates of this tuple. We set $\Phi_l=0$ if any specified coordinate index exceeds $l$. We write $\mathfrak S_l$ for the permutation group on $\{1,\,\ldots,\,l\}$ and replace $\Phi_l$ by
	\begin{equation*}
		\Phi_l^{\mathrm{sym}}(\mathbf p)=\frac1{l!}\sum_{\sigma\in\mathfrak S_l}\Phi_l(p_{\sigma(1)},\,\ldots,\,p_{\sigma(l)}),\qquad |\Phi_l^{\mathrm{sym}}(\mathbf p)|\leqslant1.
	\end{equation*}
	We sum over all ordered tuples $\mathbf p=(p_1,\,\ldots,\,p_l)\in\mathcal P_i^l$, allowing repeated primes and assigning each tuple the weight $\frac1{l!}\prod_{a=1}^l\nu_i(p_a)$. For every symmetric function $F$ on $\mathcal P_i^l$, we have
	\begin{equation*}
		\frac1{l!}\sum_{\mathbf p\in\mathcal P_i^l}\Phi_l^{\mathrm{sym}}(\mathbf p)F(\mathbf p)\prod_{a=1}^l\nu_i(p_a)=\frac1{l!}\sum_{\mathbf p\in\mathcal P_i^l}\Phi_l(\mathbf p)F(\mathbf p)\prod_{a=1}^l\nu_i(p_a).
	\end{equation*}

	For an index $a$ associated with $E_j$, we have $\mathbf1_{a\in\mathcal B_{\mathrm{act}}}=1$ precisely when its prime is chosen with weight $\nu_i(p)$ rather than taken from $\mathfrak m_i$. For the $h$th coordinate of a tuple of length $l$ appended by $G_j$, we have $\mathbf1_{a\in\mathcal B_{\mathrm{act}}}=\mathbf1_{h\leqslant l}$. We may permute the existing coordinates of $\mathfrak m_i$ without changing these indicators, and the subsequent operators commute with those permutations. We may therefore replace $\Phi_l$ by $\Phi_l^{\mathrm{sym}}$ without changing $\mathcal I(\mathcal C_0)$ or the bounds in \eqref{eq:crudebd}.

	At most $2r$ operators $E_j$ are modified; all the others satisfy \eqref{eq:esmall}. The norms of $G_j$ remain bounded, and the initial phases do not increase $\|b\|$. Consequently,
	\begin{equation*}
		|\mathcal I(\mathcal C_0)|\leqslant C_{K,\,\rho}^{2R+1}\|b\|^2L^{-G(2R-2r)+2C_*r}.
	\end{equation*}
	Summing over the collections of rank $r<r_0$ and using \eqref{eq:rankdef} gives
	\begin{equation}\label{eq:lorank}
		\begin{aligned}
			\sum_{r(\mathcal C_0)<r_0}\prod_{C\in\mathcal C_0}(|C|-1)!\,|\mathcal I(\mathcal C_0)|
			&\leqslant\sum_{r<r_0}|\mathcal B|^{2r}C_{K,\,\rho}^{2R+1}\|b\|^2L^{-G(2R-2r)+2C_*r}
			\\
			&\leqslant L^{-2RG+o(R)}\ll L^{-2R(E_0+4)}.
		\end{aligned}
	\end{equation}
	Here $r_0=o(R)$ and all parameters in $C_*$ are fixed before $x\to\infty$.

	Combining \eqref{eq:memtail}, \eqref{eq:hirank}, and \eqref{eq:lorank}, and restoring $\prod_p b'_p\leqslant1$, gives
	\begin{equation*}
		|\mathcal M_R(u,\,v,\,r)|\ll L^{-2R(E_0+4)}
	\end{equation*}
	uniformly in the real root variables. The root-averaging formula of Subsection~\ref{sec:roots}, whose measure \eqref{eq:density} has bounded total mass, now proves \eqref{eq:moment}. The one-edge assertion is precisely the corresponding conclusion of that subsection.

\label{lem:logph}
Fix $\delta,C_0>0$, suppose that $N\geqslant x^\delta$, and put $T_*=\exp(L/(\log L)^2)$. For every
subinterval $J\subset[N,2N]$ and every $T_*\leqslant |u|\leqslant x^{C_0}$, we have
\begin{equation}\label{eq:logph}
\begin{aligned}
\frac1N\bigl|\sum_{n\in J}n^{iu}\bigr|
 \ll_{\delta,\,C_0}\exp\biggl(-c_{\delta,\,C_0}\frac{L}{(\log L)^2}\biggr).
\end{aligned}
\end{equation}

Complex conjugation reduces negative frequencies to positive ones. If $T_*\leqslant u\leqslant N$, the
second-derivative estimate applied to $f(v)=u\log v/(2\pi)$ gives
\begin{equation}\label{eq:secdv}
\begin{aligned}
\bigl|\sum_{n\in J}n^{iu}\bigr|
 \ll \sqrt u+N/\sqrt u.
\end{aligned}
\end{equation}
After normalization, \eqref{eq:secdv} is at most $N^{-1/2}+T_*^{-1/2}$, which gives
\eqref{eq:logph}.

If $N\leqslant u\leqslant x^{C_0}$, set $a=C_0/\delta$, so that $u\leqslant N^a$. Choose a fixed integer $k>a$.
Starting with $B(0,1)=(1/2,1/2)$ and repeatedly applying the classical $A$-process gives the
exponent pair
\begin{equation*}
\begin{aligned}
(\kappa_k,\,\lambda_k)=A^kB(0,\,1)
 =\biggl(\frac1{2^{k+2}-2},
 1-\frac{k+1}{2^{k+2}-2}\biggr).
\end{aligned}
\end{equation*}
The logarithmic phase belongs to the phase class to which this exponent pair applies. Hence
\begin{equation*}
\begin{aligned}
\bigl|\sum_{n\in J}n^{iu}\bigr|
 \ll_k (u/N)^{\kappa_k}N^{\lambda_k}+N/u.
\end{aligned}
\end{equation*}
Consequently,
\begin{equation}\label{eq:logpw}
\begin{aligned}
\frac1N\bigl|\sum_{n\in J}n^{iu}\bigr|
 \ll_k N^{-(k+2-a)\kappa_k}+N^{-1}
 \ll_{\delta,\,C_0}x^{-c'_{\delta,\,C_0}}.
\end{aligned}
\end{equation}
This proves the stronger bound \eqref{eq:logpw}.
For the derivative test and the $A$- and $B$-processes, see
\cite[Theorem 1 and Sections 5.1--5.2]{Robert2016}.

Equation (20) in that source includes $g_0(v)=\log v$ and applies
to any $J\subset[N,2N]$. The integer $k$ is fixed throughout;
it does not grow with $X$.

\label{lem:sparse}
Fix positive constants $c$ and $C_1$. Suppose that
$cL^{0.1}\leqslant\log P\leqslant C_1L^{0.2}$, let $\mathcal P\subset[P,\,2P)$ be any set of
primes, let $\xi\in\mathbb R$, and put
\begin{equation*}
\begin{aligned}
P_s(t)=P^{-1}\sum_{p\in\mathcal P}v_p\chi(p)p^{i(t+\xi)},
 \qquad |v_p|\leqslant1.
\end{aligned}
\end{equation*}
Fix $B,A_s>0$. Let $\mathcal I$ be the family of unit intervals with integer endpoints that meet
the set
\begin{equation*}
\begin{aligned}
\{t:|t|\leqslant2XL^B,\,\ |P_s(t)|>L^{-A_s}\}
\end{aligned}
\end{equation*}
Then
\begin{equation}\label{eq:sparse}
\begin{aligned}
|\mathcal I|\leqslant\exp(O(L^{0.91})),\,\qquad
 \sum_{I\in\mathcal I}\sup_{t\in I}|N_\beta(t)|^2\ll L^{2C+1}.
\end{aligned}
\end{equation}
The implied constants may depend on the fixed parameters, and the estimates are uniform in $\xi$,
$\mathcal P$, and all coefficients satisfying $|v_p|\leqslant1$.

Take $T_0=4XL^B$ and $j=\lfloor\log T_0/\log(2P)\rfloor$, and expand
$P_s(t)^j=\sum_{u\leqslant(2P)^j}c_u u^{it}$. Unique factorization and $|\mathcal P|\leqslant 2P$ give
\begin{equation}\label{eq:pscoeff}
\begin{aligned}
\sum_u|c_u|^2\leqslant j!P^{-2j}|\mathcal P|^j
 \leqslant j!(2/P)^j.
\end{aligned}
\end{equation}
The order $j$ grows with $X$, so the factor $j!$ in
\eqref{eq:pscoeff} must be retained.

Choose a point $t_r$ with $|P_s(t_r)|>L^{-A_s}$ in each interval of $\mathcal I$. Partition the intervals into three classes according to their integer left endpoints modulo three, and fix one class. Put $F(t)=P_s(t)^j$ and $N_0=(2P)^j\leqslant T_0$. The chosen points in this class satisfy $|t_r-t_s|\geqslant1$ for $r\ne s$. The one-dimensional Sobolev estimate gives
\begin{equation}\label{eq:sobolev}
\begin{aligned}
|F(t_r)|^2\ll\int_{t_r-1/2}^{t_r+1/2}
       \bigl(|F(u)|^2+|F(u)F'(u)|\bigr)\,\mathrm{d} u.
\end{aligned}
\end{equation}
Integrating the derivative of $|F|^2$ on a unit interval, with
$|(|F|^2)'|\leqslant2|FF'|$, proves \eqref{eq:sobolev}.
The intervals centered at $t_r$ have disjoint interiors.

Apply the mean-value theorem to $F$ and to
$F'(t)=\sum_{u\leqslant N_0}(i\log u)c_u u^{it}$,
and then use Cauchy's inequality. This gives
\begin{equation*}
\begin{aligned}
\sum_r|F(t_r)|^2\ll(T_0+N_0)\log(2N_0)\sum_u|c_u|^2.
\end{aligned}
\end{equation*}
Differentiation introduces only $\log N_0\ll L$, with no additional loss from the growing order.
It follows that
\begin{equation*}
\begin{aligned}
|\mathcal I|\ll T_0L^{O(1)}L^{2A_sj}j!(2/P)^j.
\end{aligned}
\end{equation*}
Since $j\ll L^{0.9}$ and $\log T_0-j\log P\ll\log P+j$, the logarithm of the right-hand side is at
most $O(L^{0.9}\log L+L^{0.2})=O(L^{0.91})$. The factors $p^{i\xi}$ do not change the absolute
values of the coefficients, so the estimate is uniform in all $\xi$.

We now prove the energy assertion in \eqref{eq:sparse}. For each interval choose a point in its
closure at which $|N_\beta|$ attains its supremum, and again divide the intervals into three
classes according to their left endpoints modulo three.

For one class, the evaluation map $(a_n)\mapsto
 (\sum_n a_n n^{it_I})_I$ has Gram matrix
\begin{equation}\label{eq:gram}
\begin{aligned}
G_{I,\,J}=\sum_{N\leqslant n\leqslant2N}n^{i(t_I-t_J)}.
\end{aligned}
\end{equation}
The diagonal entries in \eqref{eq:gram} are $O(N)$. With $T_*$ as in Lemma~\ref{lem:logph}, when
$1\leqslant|u|\leqslant T_*$, comparison of the sum with an integral gives
\begin{equation}\label{eq:lowfreq}
\begin{aligned}
N^{-1}\bigl|\sum_{N\leqslant n\leqslant2N}n^{iu}\bigr|
 \ll |u|^{-1}+x^{-c_\delta}.
\end{aligned}
\end{equation}
Indeed, the integral is $O(N/|u|)$, the discretization error is $O(1+|u|)$, and $T_*/N\ll
x^{-c_\delta}$. For $T_*<|u|\leqslant4XL^B+2$, Lemma~\ref{lem:logph} gives \eqref{eq:logph} for the
integer phase sum.

Within the fixed class, the separation of the points gives $\sum_{J\ne I}|t_I-t_J|^{-1}\ll\log(2+|\mathcal I|)\ll L$ for every $I$. Moreover,
\begin{equation}\label{eq:gramerr}
	|\mathcal I|x^{-c_\delta}=o(1),\qquad |\mathcal I|\exp\bigl(-cL/(\log L)^2\bigr)=o(1).
\end{equation}
Together with \eqref{eq:lowfreq} and \eqref{eq:logph}, these estimates give $\max_I\sum_J|G_{I,\,J}|\ll NL$. Since the Gram matrix is Hermitian, the Schur test \eqref{eq:schur} yields
\begin{equation*}
	\sum_I|N_\beta(t_I)|^2\ll NL\sum_n\biggl|\frac{\beta_n\chi_n(n)}N\biggr|^2\ll L^{2C+1}.
\end{equation*}
Here $|N_\beta(t_I)|=\sup_{t\in I}|N_\beta(t)|$ by the choice of $t_I$. Summing over the three classes, we get the second estimate in \eqref{eq:sparse}.

\label{prop:maj}
Let $\alpha_m=\mu(m)R_Z(m)$, let $|\beta_n|\leqslant L^C$, and suppose that $\beta_n$ is supported on
$Z$-sifted integers. For the sets $\mathcal P_i$ in \eqref{eq:prime-sets} and $M,N\geqslant x^\delta$, we have
\begin{equation}\label{eq:majbd}
\begin{aligned}
|Q_Y^{\mathrm{maj}}|\ll_D XYL^{-D}
\end{aligned}
\end{equation}
for every fixed $D>0$. The two coefficient sequences may also carry the required Mellin factors,
interval restrictions, or fixed smooth cutoffs with bounded supremum norm and total variation.

Write a major arc as $\theta=h/k+\lambda/Y$, where $k\leqslant2L^{A_0}$, $|\lambda|\ll L^{A_0}$, and
$\,\mathrm{d}\theta=\,\mathrm{d}\lambda/Y$. Every prime in $\bigcup_i\mathcal P_i$ and every sifted variable is a unit
modulo $k$. Expand the function
\begin{equation*}
\begin{aligned}
(a,\,b,\,m,\,n,\,r,\,s)\longmapsto
 e\bigl(h(bmn-ars+2b-2a)/k\bigr)
\end{aligned}
\end{equation*}
exactly in multiplicative characters on the six unit groups. Each Fourier coefficient has absolute
value at most one, and there are $\varphi(k)^6$ terms, so their total absolute coefficient mass is
at most $k^6$. Fix one term of this expansion for the remainder of the argument.

Put $w=bmn/(YX)$ and $w'=ars/(YX)$.
Their ranges lie in a fixed compact subinterval of $(0,\infty)$.
Choose $\vartheta\in C_c^\infty((0,\infty))$ equal to one there.

After removing the factors $e(2\lambda b/Y)e(-2\lambda a/Y)$,
the remaining kernel is
\begin{equation*}
\begin{aligned}
\psi_{-2}(X(w-w'))e(\lambda X(w-w')).
\end{aligned}
\end{equation*}

In coordinates $z=\log w'$ and $\zeta=X\log(w/w')$, define
\begin{equation*}
\begin{aligned}
 K_\lambda(z,\,\zeta)={}&\vartheta(e^z)\vartheta(e^{z+\zeta/X})\,
 \psi_{-2}\bigl(Xe^z(e^{\zeta/X}-1)\bigr)\\
 &\hspace{9mm}\cdot
 e\bigl(\lambda Xe^z(e^{\zeta/X}-1)\bigr).
\end{aligned}
\end{equation*}
Since $\psi_{-2}$ is compactly supported, the supports of $K_\lambda$ in both $z$ and $\zeta$ lie
in fixed compact sets independent of $X$. For all nonnegative integers $j_1,j_2$,
\begin{equation*}
\begin{aligned}
\|\partial_z^{j_1}\partial_\zeta^{j_2}K_\lambda\|_\infty
 \ll_{j_1,\,j_2}L^{A_0(j_1+j_2)}.
\end{aligned}
\end{equation*}
Using the Fourier convention with $\exp(iu)$, define
\begin{equation*}
\begin{aligned}
F_\lambda(v,\,s)=\frac1{(2\pi)^2}
     \iint K_\lambda(z,\,\zeta)e^{-i(v\zeta+sz)}\,\mathrm{d} z\,\mathrm{d}\zeta.
\end{aligned}
\end{equation*}
Fourier inversion and the substitution $t=Xv$ give the exact separation
\begin{equation*}
\begin{aligned}
\psi_{-2}(X(w-w'))e(\lambda X(w-w'))
 =\frac1X\iint_{\mathbb R^2}
 F_\lambda(t/X,\,s)w^{it}(w')^{i(s-t)}\,\mathrm{d} t\,\mathrm{d} s
\end{aligned}
\end{equation*}
throughout the actual range of the variables. Integration by parts gives, for every fixed $j$,
\begin{equation}\label{eq:decay}
\begin{aligned}
|F_\lambda(v,\,s)|\ll_j
 (1+|v|/L^{B_0})^{-j}(1+|s|/L^{B_0})^{-j},
\end{aligned}
\end{equation}
where $B_0$ depends only on the major-arc width and the fixed cutoffs.

Define the polynomial over products of selected primes
\begin{equation*}
\begin{aligned}
B_{\lambda}(t)=\frac{\prod_i V_i^{-1}}Y\sum_{b\in\mathcal A}\eta(b/Y)e(2\lambda b/Y)
 \chi_b(b)b^{it},
 \qquad Q(t)=B_{\lambda}(t)M_\alpha(t)N_\beta(t).
\end{aligned}
\end{equation*}
For the characters $\chi_a,\,\chi_r,\,\chi_s$ associated with the variables $a,\,r,\,s$, respectively, define
\begin{equation*}
	Q'(u)=\frac{\prod_{i=1}^K V_i^{-1}}{YMN}\sum_{\substack{a\in\mathcal A\\r,\,\ell\geqslant1}}\eta\biggl(\frac aY\biggr)e\biggl(-\frac{2\lambda a}{Y}\biggr)\chi_a(a)\overline{\alpha_r}\chi_r(r)\overline{\beta_\ell}\chi_s(\ell)(ar\ell)^{iu}\qquad(u\in\mathbb R).
\end{equation*}
Here $\ell$ denotes the original integer variable $s$, to distinguish it from the Fourier variable $s$, and $r,\,\ell$ are restricted to the supports of $\alpha,\,\beta$, respectively. The estimates below also apply to $Q'$, with $-\lambda,\,\overline{\alpha},\,\overline{\beta}$ in place of $\lambda,\,\alpha,\,\beta$. By \eqref{eq:aharm} and $b\asymp Y$, we have
$|B_{\lambda}(t)|\ll1$. Each unnormalized endpoint is $YMN$ times the corresponding polynomial.

The substitutions for $w,w'$ also contribute the common factor $(YX)^{-is}$, whose absolute value
is one. Thus the combined scale of the two endpoints, the Mellin kernel, and the arc measure is
\begin{equation*}
\begin{aligned}
(YMN)^2\cdot X^{-1}\cdot Y^{-1}
 =XY(MN/X)^2\asymp XY.
\end{aligned}
\end{equation*}
After division by $XY$, it remains to bound the integral of $F_{\lambda}(t/X,s)Q(t)Q'(s-t)$.

To bound the tails uniformly, for
every interval $J$ of length $U\geqslant1$ and every real $s$, Cauchy's inequality and \eqref{eq:prodms}
give
\begin{equation*}
\begin{aligned}
\int_J|Q(t)Q'(s-t)|\,\mathrm{d} t\ll L^{2C+3}(1+U/X).
\end{aligned}
\end{equation*}
The estimate is uniform in $s$ because the mean-value bound holds on translated intervals. For any
fixed integer $j>2$, a dyadic decomposition in $t$ now gives
\begin{equation*}
\begin{aligned}
\int_{\mathbb R}(1+|t|/(XL^{B_0}))^{-j}|Q(t)Q'(s-t)|\,\mathrm{d} t
 \ll_j L^{2C+3+B_0}.
\end{aligned}
\end{equation*}
For $T\geqslant XL^{B_0}$, the same dyadic argument bounds the $t$-tail by
$O_j(L^{2C+3+B_0}(T/(XL^{B_0}))^{1-j})$.

The $s$-weight has integral $O_j(L^{B_0})$, and for $S\geqslant L^{B_0}$,
\begin{equation*}
\begin{aligned}
\int_{|s|>S}(1+|s|/L^{B_0})^{-j}\,\mathrm{d}s
\ll_j L^{B_0}(S/L^{B_0})^{1-j}.
\end{aligned}
\end{equation*}
Choose $B_1=B_0+2$, independently of the requested logarithmic
precision.

By \eqref{eq:decay}, the contribution outside $|s|\leqslant L^{B_1}$, $|t|\leqslant XL^{B_1}$ is at most
\begin{equation*}
\begin{aligned}
O_j\bigl(L^{2C+3+2B_0-(j-1)(B_1-B_0)}\bigr).
\end{aligned}
\end{equation*}
Increasing the fixed integer $j$ makes this smaller than any prescribed power of $L^{-1}$.

On the retained range we have $|s-t|\leqslant2XL^{B_1}$. Cauchy's inequality in $t$, followed by
integration over $s$, costs at most a further fixed factor $L^{B_1}$. It is therefore enough to
prove
\begin{equation}\label{eq:energy}
\begin{aligned}
\int_{|t|\leqslant2XL^{B_1}}
 |B_{\lambda}(t)M_\alpha(t)N_\beta(t)|^2\,dt
 \ll_A L^{-A}
\end{aligned}
\end{equation}
for every fixed $A$.

The range in \eqref{eq:energy} has length $T\asymp XL^{B_1}$.
A pointwise bound for $M_\alpha$ followed by the ordinary mean-value
bound for $N_\beta$ would leave $T/N\asymp ML^{B_1}$.

Instead, the primes selected from the sets $\mathcal P_i$ restrict the exceptional frequencies.
The sparse estimate \eqref{eq:sparse} controls $N_\beta$ on that set.

We now separate one prime selected from $\mathcal P_1$ exactly. Put
\begin{equation*}
\begin{aligned}
g_\lambda(y)=y\eta(y)e(2\lambda y),\,\qquad
 \widehat g_\lambda(\xi)=\frac1{2\pi}
     \int_0^\infty g_\lambda(y)y^{-i\xi}\,\frac{\,\mathrm{d} y}{y}.
\end{aligned}
\end{equation*}
Then $g_\lambda(y)=\int\widehat g_\lambda(\xi)y^{i\xi}\,\mathrm{d}\xi$, and integration by parts a
fixed number of times gives $\|\widehat g_\lambda\|_1\ll L^{B_2}$ for a fixed $B_2$. Since
\begin{equation*}
\begin{aligned}
B_\lambda(t)=\biggl(\prod_i V_i^{-1}\biggr)\sum_{b\in\mathcal A}\frac1b
                     g_\lambda(b/Y)\chi_b(b)b^{it},
\end{aligned}
\end{equation*}
extracting $p\in\mathcal P_1$ and writing $b=pb'$ gives the exact formula
\begin{equation}\label{eq:bfactor}
\begin{aligned}
B_\lambda(t)=\frac1{V_1}\int_{\mathbb R}
 \widehat g_\lambda(\xi)Y^{-i\xi}
 \biggl(\sum_{p\in\mathcal P_1}\frac{\chi_b(p)p^{i(t+\xi)}}p\biggr)
 H(t+\xi)\,\mathrm{d}\xi,
\end{aligned}
\end{equation}
where
\begin{equation*}
\begin{aligned}
H(u)=\prod_{i=2}^K\biggl(\frac1{V_i}
                  \sum_{p\in\mathcal P_i}\frac{\chi_b(p)p^{iu}}p\biggr),
 \qquad |H(u)|\leqslant1.
\end{aligned}
\end{equation*}
When $K=1$, the empty product is interpreted as one. Partition $\mathcal P_1$ according to $O(L)$ ordinary dyadic intervals $[P,\,2P)$.  On each such interval the prime polynomial is
\begin{equation*}
\begin{aligned}
\sum_{p\in\mathcal P_1\cap[P,\,2P)}\frac{\chi_b(p)p^{i(t+\xi)}}p
 =\frac1P\sum_{p\in\mathcal P_1\cap[P,\,2P)}
           \frac Pp\chi_b(p)p^{i(t+\xi)}.
\end{aligned}
\end{equation*}
The coefficients $P/p$ satisfy the hypothesis of Lemma~\ref{lem:sparse}. Minkowski's inequality
applied to \eqref{eq:bfactor} reduces \eqref{eq:energy} to
\begin{equation}\label{eq:penergy}
\begin{aligned}
\int_{|t|\leqslant2XL^{B_1}}
 |P_s(t)M_\alpha(t)N_\beta(t)|^2\,\mathrm{d} t\ll_A L^{-A}
\end{aligned}
\end{equation}
uniformly for all $\xi\in\mathbb R$. Increasing the requested saving by a fixed amount absorbs the
losses from the $O(L)$ dyadic blocks, $V_1^{-1}=O(1)$, and $\|\widehat g_\lambda\|_1\ll L^{B_2}$.

Apply Lemma~\ref{lem:sparse} with $B=B_1$, and let $\mathcal I$ be the resulting family of unit intervals. On the set where $|P_s(t)|\leqslant L^{-A_s}$, \eqref{eq:prodms} gives
\begin{equation*}
	\int_{\substack{|t|\leqslant2XL^{B_1}\\|P_s(t)|\leqslant L^{-A_s}}}|P_s(t)M_\alpha(t)N_\beta(t)|^2\,\mathrm dt\ll L^{-2A_s+2C+3+B_1}.
\end{equation*}
On the complementary set, use $|P_s(t)|\ll1$ and the bound $|M_\alpha(t)|\ll_{A'}L^{-A'}$ from Proposition~\ref{prop:mel}. The second estimate in \eqref{eq:sparse} then gives
\begin{equation*}
	\begin{aligned}
		\int_{\substack{|t|\leqslant2XL^{B_1}\\|P_s(t)|>L^{-A_s}}}|P_s(t)M_\alpha(t)N_\beta(t)|^2\,\mathrm dt&\ll L^{-2A'}\sum_{I\in\mathcal I}\sup_{t\in I}|N_\beta(t)|^2\ll L^{-2A'+2C+1}.
	\end{aligned}
\end{equation*}
Thus \eqref{eq:penergy} follows on taking
\begin{equation*}
	2A_s>A+2C+3+B_1,\qquad 2A'>A+2C+1.
\end{equation*}

The same argument permits a factor $m^{iv}w(m)$ in the M\"obius coefficient, where $|v|\leqslant x^{C_0}$ and $w$ is a smooth weight on $[M,\,2M]$. Indeed, throughout the integration range,
\begin{equation*}
	|t+v|\leqslant2XL^{B_1}+x^{C_0}\leqslant x^{\max(2,\,C_0+1)}
\end{equation*}
for sufficiently large $x$, so \eqref{eq:mubv} gives
\begin{equation*}
\sup_{|t|\leqslant2XL^{B_1}}\frac1M\biggl|\sum_m\mu(m)R_Z(m)\chi_m(m)m^{i(t+v)}w(m)\biggr|\ll L^{-A'}\bigl(\|w\|_\infty+\operatorname{Var}_{[M,\,2M]}(w)\bigr).
\end{equation*}
Since $|\beta_n n^{iv}|=|\beta_n|$, the additional phase preserves the hypothesis of Lemma~\ref{lem:sparse}. After absorbing the fixed logarithmic losses, \eqref{eq:energy} holds uniformly for both $Q$ and $Q'$. Cauchy's inequality therefore gives
\begin{equation*}
	\int_{|s|\leqslant L^{B_1}}\int_{|t|\leqslant XL^{B_1}}\biggl|F_\lambda\biggl(\frac tX,\,s\biggr)Q(t)Q'(s-t)\biggr|\,dt\,ds\ll  L^{B_1-A}.
\end{equation*}
Increasing the integration-by-parts order also gives
\begin{equation*}
	\iint_{\substack{|s|>L^{B_1}\ \text{or}\ |t|>XL^{B_1}}}\biggl|F_\lambda\biggl(\frac tX,\,s\biggr)Q(t)Q'(s-t)\biggr|\,dt\,ds\ll  L^{-D-9A_0-1}.
\end{equation*}
The arc count, character expansion, and $\lambda$-integration contribute factors $O(L^{2A_0})$, $O(L^{6A_0})$, and $O(L^{A_0})$, respectively. Taking $A=D+9A_0+B_1+1$, we obtain
\begin{equation*}
	|Q_Y^{\mathrm{maj}}|\ll_D XYL^{2A_0+6A_0+A_0}\bigl(L^{B_1-A}+L^{-D-9A_0-1}\bigr)\ll  XYL^{-D}.
\end{equation*}
This proves \eqref{eq:majbd}.

Fix the desired Type II precision $A_*>0$.
The coefficients in \eqref{eq:011}, namely
$\alpha_m=\mu(m)R_Z(m)m^{iv}$ and
$\beta_n=c_V(n)R_Z(n)n^{iv}$, satisfy Proposition~\ref{prop:D}.

Their size exponent is fixed. Proposition~\ref{prop:maj} then gives,
for any prescribed $D_*>0$,
\begin{equation*}
\begin{aligned}
Q_Y=Q_Y^{\mathrm{maj}}+O(XYL^{-D_*})\ll XYL^{-D_*}.
\end{aligned}
\end{equation*}
Thus \eqref{eq:CS} implies
\begin{equation}\label{eq:finalII}
\begin{aligned}
|T_Y|\ll_K XL^{-D_*/2}.
\end{aligned}
\end{equation}
Choose $B>A_*+2$ and truncate the Mellin integrals with error $O_K(xL^{2-B})$. Let $C_1>0$ be a fixed exponent such that the dyadic decompositions and retained Mellin integrals together contribute a factor $O_K(L^{C_1})$, with $C_1$ independent of $K$ and the exponents $a_i$. Choose
\begin{equation*}
	D_*>2(A_*+C_1),\qquad E_0>D_*+4C+2,
\end{equation*}
and then fix $A_0,K$ as required by Proposition~\ref{prop:D}. For this fixed $K$, Proposition~\ref{prop:mel} and \eqref{eq:majbd} allow any prescribed logarithmic saving. Thus $K$ may depend on $A_*$, but no subsequent enlargement is needed.

Combining \eqref{eq:finalII} with the smoothing error from Subsection~\ref{sec:cauchy}, we obtain
\begin{equation*}
	|T_3(F)|\ll_{A_*,\,K}xL^{C_1-D_*/2}+xL^{2-B}+x^{1/2}L\ll_{A_*,\,K}xL^{-A_*}.
\end{equation*}

Combining \eqref{eq:vaughan}, \eqref{eq:typeI}, and \eqref{eq:finalII}, we obtain, for each fixed choice of the sets $\mathcal P_1,\ldots,\mathcal P_K$,
\begin{equation}\label{eq:marked}
\begin{aligned}
\sum_{x<p\leqslant2x}(\log p)\mu(p+2)\mathcal W(p+2)=o(x).
\end{aligned}
\end{equation}
The value of $K$ used here is independent of the particular exponents $a_i$. Since the mark is
bounded, the prime-power error is $O_K(x^{1/2}L^2)$.

Fix a positive integer $b$. Choose $bK$ distinct exponents in
$(0.1,\,0.2)$ and partition them into $b$ groups of $K$ exponents each.
For each group, define a weight $\mathcal W_j$ by \eqref{eq:prime-sets}
and \eqref{eq:mark}. The $bK$ sets of primes used to define these weights
are pairwise disjoint for sufficiently large $x$.

Finally, applying \eqref{eq:marked} to each $\mathcal W_j$ and then using
Proposition~\ref{prop:rem}, we get
\begin{equation*}
\begin{aligned}
\limsup_{x\to\infty}\frac{1}{x}\,\bigg|\sum_{x<p\leqslant2x}\mu(p+2)\log p
\bigg|\leqslant\sqrt{C_{K,\,\rho}/b}.
\end{aligned}
\end{equation*}
Let first $x\to\infty$ with $b$ fixed, and then let $b\to\infty$, one gets
\begin{align}\label{2-dy}
	\sum_{x<p\leqslant2x}\mu(p+2)\log p=o(x).
\end{align}
Then, summing \eqref{2-dy} over dyadic intervals, we arrive at
\begin{equation*}
\begin{aligned}

\sum_{p\leqslant x}\mu(p+2)\log p=o(x),
\end{aligned}
\end{equation*}
and Theorem~\ref{thm:main} follows immediately from this estimate by partial summation.

\label{prop:squarefree-density}
For every fixed integer $h\ne0$ and every $A>0$,
\begin{equation}\label{eq:sf-asymptotic}
 \sum_{\substack{1\leqslant n\leqslant x\\n+h\geqslant 1}}\Lambda(n)\mu^2(n+h)
 =A_hx+O_{A,h}\bigg(\frac{x}{(\log x)^A}\bigg),
 \quad\text{with}\quad A_h:=\prod_{p\nmid h}\bigg(1-\frac1{p(p-1)}\bigg)>0.
\end{equation}

In the following we omit the condition $n+h\geqslant 1$ for notation simplicity.
	First, it is easy to see that it suffices to consider the sum
	$$
	\sum_{\substack{p\leqslant x,\, p\,\nmid\, h}}\mu^2(p+h)\log p.
	$$
For these $p\,\nmid\, h$, we have 
\begin{equation}\label{eq:sf-mobius-inversion}
	\mu^2(p+h)=\sum_{d^2\mid p+h}\mu(d),
\end{equation}
and hence  $(d,\,h)=1$.

Recall that $L=\log x$.
The terms with $d>L^{A+2}$ have total absolute contribution at most
\begin{equation}\label{eq:sf-large-tail}
 L\sum_{d>L^{A+2}}
 \bigg\lfloor\frac{x+|h|}{d^2}\bigg\rfloor
 \ll_{A,h}\frac{x}{L^{A+1}}.
\end{equation}

For $(d,h)=1$ and $d\leqslant L^{A+2}$, the Siegel--Walfisz theorem (see \cite[Theorem 12.1]{kouk}) gives
\begin{equation}\label{eq:sf-small-moduli}
 \sum_{\substack{p\leqslant x\\p\equiv-h\,(\mathrm{mod}\,d^2)}}\log p
 =\frac{x}{\varphi(d^2)}+O_A(xL^{-2A-4}).
\end{equation}
Restoring the omitted primes dividing $h$ and the finitely many
primes with $p+h\leqslant0$ costs $O_h(L^{A+2})$ after summation over $d$.
Thus \eqref{eq:sf-mobius-inversion}--\eqref{eq:sf-small-moduli} imply
\begin{equation}\label{eq:sf-small-main}
 \sum_{\substack{n\leqslant x\\n+h\geqslant1}}\Lambda(n)\mu^2(n+h)
 =x\sum_{\substack{d\leqslant L^{A+2}\\(d,h)=1}}
      \frac{\mu(d)}{\varphi(d^2)}+O_{A,h}(xL^{-A}).
\end{equation}

Since $1/\varphi(d^2)\leqslant\tau(d)/d^2$ and
$\sum_{d\leqslant t}\tau(d)\ll t\log(2t)$, partial summation gives
\begin{equation}\label{eq:sf-coefficient-tail}
 \sum_{d>L^{A+2}}\frac{|\mu(d)|}{\varphi(d^2)}
 \ll_A\frac{\log L}{L^{A+2}}.
\end{equation}
The absolutely convergent Euler product is
\begin{equation}\label{eq:sf-euler-product}
 \sum_{\substack{d\geqslant1\\(d,h)=1}}\frac{\mu(d)}{\varphi(d^2)}
 =\prod_{p\nmid h}\bigg(1-\frac1{p(p-1)}\bigg)=A_h>0.
\end{equation}
 Combining \eqref{eq:sf-small-main}--\eqref{eq:sf-euler-product}, we 
complete the proof of Proposition \ref{prop:squarefree-density}.

Theorem \ref{thm2} is an immediately consequence of Theorem \ref{thm:main} and  Proposition \ref{prop:squarefree-density}. To see this, we first apply partial	summation to the asymptotic formula \eqref{eq:sf-asymptotic} with $h=2$, getting
	\begin{equation}\label{eq:sf-prime-count}
		\sum_{p\leqslant x}\mu^2(p+2)=\big(A_2+o(1)\big)\pi(x).
	\end{equation}
	Next, note that for $\kappa\in\{-1,1\}$, we have 
	$$\mathbf{1}_{\{\mu(m)=\kappa\}}=\frac{\mu^2(m)+\kappa\mu(m)}{2}.$$
	This identity, together with \eqref{eq:sf-prime-count} and
	Theorem~\ref{thm:main}, gives
	\begin{align*}
		\Big|\big\{p\leqslant x:\ \mu(p+2)=\kappa\big\}\Big|
		=\frac12\sum_{p\leqslant x}\mu^2(p+2)
		+\frac{\kappa}{2}\sum_{p\leqslant x}\mu(p+2)=\bigg(\frac{A_2}{2}+o(1)\bigg)\pi(x).
	\end{align*}

\label{lem:app-root-count}
	Suppose that $d_0YM,\,N\geqslant2$, and let $S$ be a squarefree positive integer. For positive coprime integers $u,\,v$, let
	\begin{equation*}
		g=\begin{pmatrix}u&c\\v&d\end{pmatrix}\in\mathrm{SL}_2(\mathbb Z),\qquad 0\leqslant c<u,
	\end{equation*}
	be the normalized completion of $(u,\,v)^T$. For $g_0\in\mathrm{SL}_2(\mathbb Z/S\mathbb Z)$ and intervals $I_1,\,I_2\subseteq[1,\,16]$ and $I_3\subseteq[0,\,1]$, we have
	\begin{equation}\label{eq:app-root-count}
		\begin{aligned}
			\sum_{\substack{u,\,v\geqslant1,\,(u,\,v)=1\\ \frac{u}{d_0YM}\in I_1,\,\frac vN\in I_2\\ \frac cu\in I_3,\,g\equiv g_0\,(\textrm{mod}\,S)}}1&=\frac{d_0YMN\,|I_1||I_2||I_3|}{\zeta(2)|\mathrm{SL}_2(\mathbb Z/S\mathbb Z)|}+O\Bigl(d_0YMN\,S^2\min\{d_0YM,\,N\}^{\frac{-1}{100}}\Bigr).
		\end{aligned}
	\end{equation}

We first prove an exponential-sum bound for arbitrary moduli. For $m\geqslant2$ and integers $h,\,k$, put
	\begin{equation*}
		K_m(h,\,k)=\sum_{\substack{y\,(\textrm{mod}\,m)\\(y,\,m)=1}}e\biggl(\frac{hy+ky^{-1}}m\biggr),
	\end{equation*}
	where $y^{-1}$ denotes the inverse of $y$ modulo $m$. Additive orthogonality gives
	\begin{equation*}
		\sum_{h,\,k\,(\textrm{mod}\,m)}|K_m(h,\,k)|^4=m^2T_m,
	\end{equation*}
	where $T_m$ counts quadruples of units $y_1,\,y_2,\,z_1,\,z_2$ modulo $m$ satisfying
	\begin{equation*}
		y_1+y_2\equiv z_1+z_2\,(\textrm{mod}\,m),\qquad y_1^{-1}+y_2^{-1}\equiv z_1^{-1}+z_2^{-1}\,(\textrm{mod}\,m).
	\end{equation*}
	Substituting $z_2=y_1+y_2-z_1$ into the second congruence and multiplying by $y_1y_2z_1z_2$ gives
	\begin{equation*}
		m\mid(y_1+y_2)(z_1-y_1)(z_1-y_2).
	\end{equation*}
	The map $(y_1,\,y_2,\,z_1)\mapsto(y_1+y_2,\,z_1-y_1,\,z_1-y_2)$ has kernel $\{(t,\,-t,\,t):\ 2t\equiv0\,(\textrm{mod}\,m)\}$, of size at most two. Every triple $(a_1,\,a_2,\,a_3)$ with $m\mid a_1a_2a_3$ satisfies $d_1\mid a_1$, $d_2\mid a_2$, and $d_3\mid a_3$ for some $d_1d_2d_3=m$, by distributing the exponent of each prime among the three factors. Thus, with $\tau_3(m)$ denoting the number of ordered factorizations $m=d_1d_2d_3$,
	\begin{equation*}
		T_m\leqslant2\sum_{d_1d_2d_3=m}\frac m{d_1}\frac m{d_2}\frac m{d_3}=2m^2\tau_3(m).
	\end{equation*}

	For every unit $s$ modulo $m$, substitution in the defining sum gives $K_m(hs,\,ks^{-1})=K_m(h,\,k)$. The stabilizer consists of the units satisfying $s\equiv1\,(\textrm{mod}\,m/(h,\,k,\,m))$. Reduction between the corresponding unit groups is surjective, so there are exactly $\varphi(m/(h,\,k,\,m))$ distinct pairs $(hs,\,ks^{-1})$. Consequently,
	\begin{equation*}
		|K_m(h,\,k)|^4\leqslant\frac{2m^4\tau_3(m)}{\varphi(m/(h,\,k,\,m))}.
	\end{equation*}
	Using $\tau_3(m)\ll_\varepsilon m^\varepsilon$ and $m/\varphi(m)\ll_\varepsilon m^\varepsilon$, which follow by separating the finitely many small primes, we obtain
	\begin{equation}\label{eq:app-kloosterman}
		|K_m(h,\,k)|\ll_\varepsilon m^{3/4+\varepsilon}(h,\,k,\,m)^{1/4}.
	\end{equation}
	This includes even moduli and frequencies not coprime to the modulus.

	Suppose first that $d_0YM\leqslant N$. Choose integer representatives $g_0=\begin{pmatrix}u_0&c_0\\v_0&d'_0\end{pmatrix}$ and fix $u\equiv u_0\,(\textrm{mod}\,S)$. Let $\mathscr R_u$ be the set of pairs $(c,\,v)$ modulo $uS$ satisfying
	\begin{equation*}
		c\equiv c_0\,(\textrm{mod}\,S),\qquad v\equiv v_0\,(\textrm{mod}\,S),\qquad cv\equiv ud'_0-1\,(\textrm{mod}\,uS).
	\end{equation*}
	These congruences are equivalent to the prescribed matrix congruence once $d=\frac{1+cv}u$. The last congruence implies $(u,\,c)=(u,\,v)=1$. At primes dividing both $u$ and $S$, coprimality of $c$ and $u$ follows from $u_0d'_0-c_0v_0\equiv1\,(\textrm{mod}\,S)$; at the other primes dividing $u$, it excludes the proportion $1/p$ of possible lifts. For each admissible $c$, writing $v=v_0+Sj$ gives a unique $j$ modulo $u$. Therefore
	\begin{equation*}
		\#\mathscr R_u=u\prod_{\substack{p\mid u,\ p\nmid S}}\biggl(1-\frac1p\biggr).
	\end{equation*}

	We next show that the pairs in $\mathscr R_u$ are uniformly distributed in rectangles of the torus $(\mathbb R/\mathbb Z)^2$. Put $S_1=(u,\,S)$ and $S_2=\frac S{S_1}$, and choose $\gamma$ with $\gamma S_2\equiv1\,(\textrm{mod}\,uS_1)$. Since $S$ is squarefree, $(S_2,\,uS_1)=1$. Modulo $S_2$, both coordinates are fixed; modulo $uS_1$, they satisfy $cv\equiv ud'_0-1$ and $c\equiv c_0\,(\textrm{mod}\,S_1)$. The latter condition also forces $v\equiv v_0\,(\textrm{mod}\,S_1)$. The Chinese remainder theorem and additive orthogonality give
	\begin{equation*}
		\biggl|\sum_{(c,\,v)\in\mathscr R_u}e\biggl(\frac{hc+kv}{uS}\biggr)\biggr|\leqslant\frac1{S_1}\sum_{j\,(\textrm{mod}\,S_1)}\bigl|K_{uS_1}\bigl(\gamma h+ju,\,\gamma k(ud'_0-1)\bigr)\bigr|.
	\end{equation*}
	Both $\gamma$ and $ud'_0-1$ are coprime to $uS_1$. For $0<\max\{|h|,\,|k|\}\leqslant u^{0.02}$, we have
	\begin{equation*}
		(\gamma h+ju,\,\gamma k(ud'_0-1),\,uS_1)\leqslant S_1(h,\,k,\,u)\leqslant S_1u^{0.02}.
	\end{equation*}
	Applying \eqref{eq:app-kloosterman} with $\varepsilon=1/200$ we have for $0<\max\{|h|,\,|k|\}\leqslant u^{0.02}$
	\begin{equation}\label{eq:app-root-fourier}
		\biggl|\sum_{(c,\,v)\in\mathscr R_u}e\biggl(\frac{hc+kv}{uS}\biggr)\biggr|\ll u^{0.760}S_1^{1.005}\leqslant u^{0.760}S^2.
	\end{equation}

	To pass from \eqref{eq:app-root-fourier} to interval counts, take $\Delta=\frac1{100}u^{-0.01}$. For any interval $J$ in $\mathbb R/\mathbb Z$, enlargement or contraction by $2\Delta$, followed by convolution with a smooth probability density supported within distance $\Delta$, gives functions $f_J^-,\,f_J^+$ satisfying
	\begin{equation*}
		0\leqslant f_J^-\leqslant\mathbf1_J\leqslant f_J^+\leqslant1,\qquad \widehat f_J^\pm(0)=|J|+O(\Delta),\qquad |\widehat f_J^\pm(n)|\ll_j(1+\Delta|n|)^{-j}.
	\end{equation*}
	Here $\widehat f(n)=\int_0^1f(t)e(-nt)\,dt$. If $|J|<4\Delta$, take $f_J^-=0$; if the enlarged interval fills the circle, take $f_J^+=1$. The same bounds remain valid. For either choice of sign,
	\begin{equation*}
		\sum_{n\in\mathbb Z}|\widehat f_J^\pm(n)|\ll\Delta^{-1},\qquad \sum_{|n|>u^{0.02}}|\widehat f_J^\pm(n)|\ll\Delta^{-10}(u^{0.02})^{-9}.
	\end{equation*}
	Apply the products of these upper and lower functions to two torus intervals $J_1,\,J_2$. The zero frequency contributes $(\#\mathscr R_u)|J_1||J_2|+O(u\Delta)$. There are $O(u^{0.04})$ nonzero frequency pairs with $\max\{|h|,\,|k|\}\leqslant u^{0.02}$, while
	\begin{equation*}
		\sum_{\max\{|h|,\,|k|\}>u^{0.02}}|\widehat f_{J_1}^\pm(h)\widehat f_{J_2}^\pm(k)|\ll\Delta^{-11}(u^{0.02})^{-9}\ll u^{-0.07}.
	\end{equation*}
	Using the trivial bound $\#\mathscr R_u\leqslant u$ for these remaining frequencies, we obtain
	\begin{equation}\label{eq:app-root-discrepancy}
		\begin{aligned}
			\biggl|\sum_{(c,\,v)\in\mathscr R_u}\mathbf1_{J_1}\biggl(\frac c{uS}\biggr)\mathbf1_{J_2}\biggl(\frac v{uS}\biggr)-(\#\mathscr R_u)|J_1||J_2|\biggr|&\ll u^{0.99}+u^{0.80}S^2+u^{0.93}\ll u^{0.99}S^2.
		\end{aligned}
	\end{equation}
	The arguments of the indicators are taken modulo one. In particular, the error is independent of the lengths and locations of $J_1,\,J_2$.

	For fixed $u$, the restriction $\frac cu\in I_3$ corresponds to a torus interval of length $\frac{|I_3|}S$. Split the interval $NI_2$ for $v$ at multiples of $uS$; it has $O(\frac Nu+1)$ pieces, with total normalized length $\frac{N|I_2|}{uS}$. Thus \eqref{eq:app-root-discrepancy} gives
	\begin{equation*}
		\sum_{\substack{v,\,c\in\mathbb Z,\,0\leqslant c<u\\ \frac vN\in I_2,\,\frac cu\in I_3\\ (c,\,v)\,(\textrm{mod}\,uS)\in\mathscr R_u}}1=\frac{N|I_2||I_3|}{S^2}\prod_{\substack{p\mid u\\p\nmid S}}\biggl(1-\frac1p\biggr)+O\bigl((\frac Nu+1)u^{0.99}S^2\bigr).
	\end{equation*}
	Summing the errors over $u\in d_0YM I_1$ gives $O(d_0YMN(d_0YM)^{-0.01}S^2)$. To sum the main terms, expand the product into divisors. Since $(\ell,\,S)=1$, the conditions $\ell\mid u$ and $u\equiv u_0\,(\textrm{mod}\,S)$ specify one residue class modulo $\ell S$, whether or not $(u_0,\,S)=1$. Consequently,
	\begin{equation*}
		\begin{aligned}
			\sum_{\substack{\frac u{d_0YM}\in I_1\\u\equiv u_0\,(\textrm{mod}\,S)}}\prod_{\substack{p\mid u\\p\nmid S}}\biggl(1-\frac1p\biggr)&=\sum_{\substack{\ell\leqslant16d_0YM\\(\ell,\,S)=1}}\frac{\mu(\ell)}\ell\biggl(\frac{d_0YM|I_1|}{\ell S}+O(1)\biggr)\\
			&=\frac{d_0YM|I_1|}{S\zeta(2)}\prod_{p\mid S}(1-p^{-2})^{-1}+O\bigl(\log(2d_0YM)\bigr).
		\end{aligned}
	\end{equation*}
	Here extending the series in $\ell$ to infinity costs $O(1/S)$. Since
	\begin{equation*}
		|\mathrm{SL}_2(\mathbb Z/S\mathbb Z)|=\prod_{p\mid S}p(p^2-1)=S^3\prod_{p\mid S}(1-p^{-2}),
	\end{equation*}
	we obtain the main term in \eqref{eq:app-root-count}. The additional error is absorbed because
	\begin{equation*}
		\frac{N\log(2d_0YM)}{S^2}\ll d_0YMN(d_0YM)^{-0.01}S^2.
	\end{equation*}

	Finally suppose that $N<d_0YM$. Since $u,\,v>1$, the normalization $0\leqslant c<u$ implies $0<d<v$. The matrix
	\begin{equation*}
		\widetilde g=\begin{pmatrix}v&v-d\\u&u-c\end{pmatrix}\in\mathrm{SL}_2(\mathbb Z),\qquad \frac{v-d}{v}=1-\frac cu-\frac1{uv},
	\end{equation*}
	is the normalized completion of $(v,\,u)^T$, and $g\mapsto\widetilde g$ is an involution, also modulo $S$. Apply the case already proved with the two coordinate scales and intervals interchanged. The condition $\frac cu\in I_3$ is bounded above and below by requiring $\frac{v-d}{v}$ to lie in the interval $1-I_3$ enlarged or contracted by $\frac1{d_0YMN}$, with intersection with $[0,\,1]$. These changes alter the predicted main term by $O(1)$, which is absorbed by the error in \eqref{eq:app-root-count}. This proves the lemma for both orders of the coordinate scales.
